{
  "name": "Graph Pro Studio",
  "description": "A professional, modular 3D graph visualization tool. Create nodes, connect edges, and manage knowledge graphs with a spatial interface. Built for React and ready for desktop packaging."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import * as THREE from 'three';

export interface GraphNodeData {
  id: string;
  label: string;
  summary: string;
  fullContent: string;
  color: string;
  size: number;
  position: [number, number, number];
}

export interface GraphEdgeData {
  id: string;
  fromId: string;
  toId: string;
  label: string;
  color: string;
}

export interface CameraState {
  x: number;
  y: number;
  z: number;
}

export type InteractionMode = 'select' | 'edge-start' | 'edge-finish';

export interface AppState {
  nodes: GraphNodeData[];
  edges: GraphEdgeData[];
  activeId: string | null; // ID of selected node or edge
  activeType: 'node' | 'edge' | null;
  mode: InteractionMode;
  edgeStartNodeId: string | null;
}

import React, { useRef, useState } from 'react';
import { ThreeEvent, useFrame } from '@react-three/fiber';
import { Text } from '@react-three/drei';
import * as THREE from 'three';
import { GraphNodeData } from '../types';

interface GraphNodeProps {
  data: GraphNodeData;
  isSelected: boolean;
  isEdgeStart: boolean;
  onClick: (e: ThreeEvent<MouseEvent>, id: string) => void;
  onPointerOver: (e: ThreeEvent<PointerEvent>, data: GraphNodeData) => void;
  onPointerOut: (e: ThreeEvent<PointerEvent>) => void;
  onDrag: (id: string, newPos: [number, number, number]) => void;
  isDraggingEnabled: boolean;
}

export const GraphNode: React.FC<GraphNodeProps> = ({
  data,
  isSelected,
  isEdgeStart,
  onClick,
  onPointerOver,
  onPointerOut,
  onDrag,
  isDraggingEnabled
}) => {
  const meshRef = useRef<THREE.Mesh>(null);
  const [dragging, setDragging] = useState(false);
  const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
  const planeIntersectPoint = new THREE.Vector3();

  const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
    if (!isDraggingEnabled) return;
    e.stopPropagation();
    // Only allow left click drag
    if (e.button === 0) {
      setDragging(true);
      // Capture pointer to ensure we receive move events even if mouse leaves the mesh
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
    }
  };

  const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
    if (dragging) {
      setDragging(false);
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    }
  };

  const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
    if (dragging && isDraggingEnabled) {
      e.stopPropagation();
      // Raycast to the XZ plane
      e.ray.intersectPlane(plane, planeIntersectPoint);
      onDrag(data.id, [planeIntersectPoint.x, 0, planeIntersectPoint.z]);
    }
  };

  // Visual feedback
  const emissiveColor = isSelected ? '#444444' : (isEdgeStart ? '#00ff00' : '#000000');
  const scale = dragging ? data.size * 1.1 : data.size;

  return (
    <group position={data.position}>
      <mesh
        ref={meshRef}
        onClick={(e) => onClick(e, data.id)}
        onPointerOver={(e) => onPointerOver(e, data)}
        onPointerOut={onPointerOut}
        onPointerDown={handlePointerDown}
        onPointerUp={handlePointerUp}
        onPointerMove={handlePointerMove}
        scale={[scale, scale, scale]}
      >
        <sphereGeometry args={[0.7, 32, 32]} />
        <meshStandardMaterial
          color={data.color}
          emissive={emissiveColor}
          emissiveIntensity={0.5}
          roughness={0.3}
          metalness={0.2}
        />
      </mesh>

      {/* Text Label */}
      <Text
        position={[0, 1.2 * data.size, 0]}
        fontSize={0.5}
        color="black"
        anchorX="center"
        anchorY="middle"
        outlineWidth={0.02}
        outlineColor="white"
      >
        {data.label}
      </Text>
    </group>
  );
};

import React, { useMemo } from 'react';
import { ThreeEvent } from '@react-three/fiber';
import * as THREE from 'three';
import { GraphEdgeData, GraphNodeData } from '../types';

interface GraphEdgeProps {
  data: GraphEdgeData;
  fromNode?: GraphNodeData;
  toNode?: GraphNodeData;
  isSelected: boolean;
  onClick: (e: ThreeEvent<MouseEvent>, id: string) => void;
  onPointerOver: (e: ThreeEvent<PointerEvent>, data: GraphEdgeData) => void;
  onPointerOut: (e: ThreeEvent<PointerEvent>) => void;
}

export const GraphEdge: React.FC<GraphEdgeProps> = ({
  data,
  fromNode,
  toNode,
  isSelected,
  onClick,
  onPointerOver,
  onPointerOut
}) => {
  if (!fromNode || !toNode) return null;

  const start = new THREE.Vector3(...fromNode.position);
  const end = new THREE.Vector3(...toNode.position);
  const distance = start.distanceTo(end);

  // Calculate orientation
  const midPoint = start.clone().add(end).multiplyScalar(0.5);
  const direction = end.clone().sub(start).normalize();
  const quaternion = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction);

  const emissiveColor = isSelected ? '#444444' : '#000000';

  return (
    <group position={midPoint} quaternion={quaternion}>
      <mesh
        onClick={(e) => onClick(e, data.id)}
        onPointerOver={(e) => onPointerOver(e, data)}
        onPointerOut={onPointerOut}
      >
        <cylinderGeometry args={[0.1, 0.1, distance, 8]} />
        <meshStandardMaterial 
          color={data.color} 
          emissive={emissiveColor}
          emissiveIntensity={0.5}
        />
      </mesh>
    </group>
  );
};

import React, { useState } from 'react';
import { 
  Plus, Link as LinkIcon, Download, Upload, 
  Trash2, Save, MapPin, ChevronUp, ChevronDown, 
  Settings, Camera, FileJson, MousePointer2 
} from 'lucide-react';
import { AppState, GraphNodeData, GraphEdgeData } from '../types';

interface UIOverlayProps {
  appState: AppState;
  nodes: GraphNodeData[];
  edges: GraphEdgeData[];
  cameraPos: { x: number; y: number; z: number };
  onAddNode: () => void;
  onToggleEdgeMode: () => void;
  onUpdateItem: (id: string, type: 'node' | 'edge', data: Partial<GraphNodeData | GraphEdgeData>) => void;
  onDeleteItem: () => void;
  onExport: () => void;
  onImport: (file: File) => void;
  onCameraTeleport: (x: number, y: number, z: number) => void;
  hoverInfo: { label: string; summary: string; full: string } | null;
}

const Panel: React.FC<{ title: string; icon: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean }> = ({ 
  title, icon, children, defaultOpen = true 
}) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  return (
    <div className="bg-white/95 backdrop-blur-sm border border-gray-200 rounded-lg shadow-lg mb-4 overflow-hidden w-64 transition-all duration-200">
      <div 
        className="bg-gray-100 p-2 flex items-center justify-between cursor-pointer hover:bg-gray-200 select-none"
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="flex items-center gap-2 text-sm font-bold text-gray-700">
          {icon}
          <span>{title}</span>
        </div>
        {isOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
      </div>
      {isOpen && <div className="p-3 text-sm">{children}</div>}
    </div>
  );
};

export const UIOverlay: React.FC<UIOverlayProps> = ({
  appState, nodes, edges, cameraPos,
  onAddNode, onToggleEdgeMode, onUpdateItem, onDeleteItem,
  onExport, onImport, onCameraTeleport, hoverInfo
}) => {
  const [camInput, setCamInput] = useState({ x: 0, y: 10, z: 20 });

  // Find active item
  const activeNode = appState.activeType === 'node' ? nodes.find(n => n.id === appState.activeId) : null;
  const activeEdge = appState.activeType === 'edge' ? edges.find(e => e.id === appState.activeId) : null;

  return (
    <>
      {/* Tooltip Modal */}
      {hoverInfo && (
        <div 
          className="fixed z-50 pointer-events-none bg-gray-900/90 text-white p-3 rounded-md shadow-xl border border-gray-600 max-w-xs"
          style={{ left: '50%', top: '50%', transform: 'translate(-50%, -50%)' }} // Simplified center for this demo, ideally follows mouse
        >
          <div className="font-bold text-lg mb-1">{hoverInfo.label}</div>
          <div className="text-gray-300 text-xs mb-2 border-b border-gray-600 pb-2">{hoverInfo.summary}</div>
          <div className="text-gray-400 text-xs whitespace-pre-wrap">{hoverInfo.full}</div>
        </div>
      )}

      {/* Right Sidebar */}
      <div className="absolute top-4 right-4 z-10 flex flex-col max-h-[90vh] overflow-y-auto pr-1">

        {/* Tools Panel */}
        <Panel title="ابزارها" icon={<Settings size={16} />}>
          <div className="flex flex-col gap-2">
            <button 
              onClick={onAddNode}
              className="flex items-center justify-center gap-2 bg-blue-500 hover:bg-blue-600 text-white p-2 rounded transition-colors"
            >
              <Plus size={16} />
              <span>نود جدید</span>
            </button>
            <button 
              onClick={onToggleEdgeMode}
              className={`flex items-center justify-center gap-2 p-2 rounded transition-colors text-white ${
                appState.mode !== 'select' ? 'bg-green-600 ring-2 ring-green-300' : 'bg-gray-500 hover:bg-gray-600'
              }`}
            >
              <LinkIcon size={16} />
              <span>{appState.mode === 'select' ? 'ایجاد یال (اتصال)' : 'لغو حالت اتصال'}</span>
            </button>
            {appState.mode !== 'select' && (
              <div className="text-xs text-center text-orange-600 font-bold bg-orange-100 p-1 rounded">
                {appState.mode === 'edge-start' ? 'نود مبدا را انتخاب کنید' : 'نود مقصد را انتخاب کنید'}
              </div>
            )}
          </div>
        </Panel>

        {/* File Panel */}
        <Panel title="فایل پروژه" icon={<FileJson size={16} />}>
          <div className="flex flex-col gap-2">
            <button onClick={onExport} className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white p-2 rounded">
              <Download size={16} /> <span>دانلود فایل JSON</span>
            </button>
            <label className="flex items-center justify-center gap-2 bg-amber-500 hover:bg-amber-600 text-white p-2 rounded cursor-pointer">
              <Upload size={16} /> <span>بارگذاری فایل</span>
              <input type="file" className="hidden" accept=".json" onChange={(e) => e.target.files?.[0] && onImport(e.target.files[0])} />
            </label>
          </div>
        </Panel>

      </div>

      {/* Left Sidebar */}
      <div className="absolute top-4 left-4 z-10 flex flex-col max-h-[90vh] overflow-y-auto pl-1">

        {/* Properties Panel */}
        <Panel title="تنظیمات آیتم" icon={<MousePointer2 size={16} />}>
          {activeNode && (
            <div className="flex flex-col gap-3">
              <div>
                <label className="text-xs text-gray-500 block mb-1">نام / لیبل</label>
                <input 
                  type="text" 
                  className="w-full border rounded p-1 text-sm" 
                  value={activeNode.label}
                  onChange={(e) => onUpdateItem(activeNode.id, 'node', { label: e.target.value })}
                />
              </div>
              <div>
                <label className="text-xs text-gray-500 block mb-1">اندازه</label>
                <input 
                  type="range" min="0.5" max="3" step="0.1" 
                  className="w-full"
                  value={activeNode.size}
                  onChange={(e) => onUpdateItem(activeNode.id, 'node', { size: parseFloat(e.target.value) })}
                />
              </div>
              <div>
                <label className="text-xs text-gray-500 block mb-1">رنگ</label>
                <input 
                  type="color" 
                  className="w-full h-8 cursor-pointer rounded border border-gray-300"
                  value={activeNode.color}
                  onChange={(e) => onUpdateItem(activeNode.id, 'node', { color: e.target.value })}
                />
              </div>
              <hr className="border-gray-200" />
              <div>
                <label className="text-xs text-gray-500 block mb-1">خلاصه (Summary)</label>
                <textarea 
                  className="w-full border rounded p-1 text-sm h-16"
                  value={activeNode.summary}
                  onChange={(e) => onUpdateItem(activeNode.id, 'node', { summary: e.target.value })}
                />
              </div>
              <div>
                <label className="text-xs text-gray-500 block mb-1">محتوای کامل (RAG)</label>
                <textarea 
                  className="w-full border rounded p-1 text-sm h-24"
                  value={activeNode.fullContent}
                  onChange={(e) => onUpdateItem(activeNode.id, 'node', { fullContent: e.target.value })}
                />
              </div>
              <button onClick={onDeleteItem} className="mt-2 bg-red-500 hover:bg-red-600 text-white p-2 rounded flex items-center justify-center gap-2">
                <Trash2 size={16} /> <span>حذف نود</span>
              </button>
            </div>
          )}

          {activeEdge && (
            <div className="flex flex-col gap-3">
               <div>
                <label className="text-xs text-gray-500 block mb-1">برچسب یال</label>
                <input 
                  type="text" 
                  className="w-full border rounded p-1 text-sm" 
                  value={activeEdge.label}
                  onChange={(e) => onUpdateItem(activeEdge.id, 'edge', { label: e.target.value })}
                />
              </div>
              <div>
                <label className="text-xs text-gray-500 block mb-1">رنگ یال</label>
                <input 
                  type="color" 
                  className="w-full h-8 cursor-pointer rounded border border-gray-300"
                  value={activeEdge.color}
                  onChange={(e) => onUpdateItem(activeEdge.id, 'edge', { color: e.target.value })}
                />
              </div>
              <button onClick={onDeleteItem} className="mt-2 bg-red-500 hover:bg-red-600 text-white p-2 rounded flex items-center justify-center gap-2">
                <Trash2 size={16} /> <span>حذف یال</span>
              </button>
            </div>
          )}

          {!activeNode && !activeEdge && (
            <div className="text-center text-gray-400 py-4 text-xs">
              هیچ آیتمی انتخاب نشده است
            </div>
          )}
        </Panel>

        {/* Camera Panel */}
        <Panel title="موقعیت دوربین" icon={<Camera size={16} />}>
           <div className="flex gap-1 mb-2">
              <input type="number" placeholder="X" className="w-1/3 border rounded p-1 text-xs" value={camInput.x} onChange={e => setCamInput({...camInput, x: parseFloat(e.target.value)})} />
              <input type="number" placeholder="Y" className="w-1/3 border rounded p-1 text-xs" value={camInput.y} onChange={e => setCamInput({...camInput, y: parseFloat(e.target.value)})} />
              <input type="number" placeholder="Z" className="w-1/3 border rounded p-1 text-xs" value={camInput.z} onChange={e => setCamInput({...camInput, z: parseFloat(e.target.value)})} />
           </div>
           <button 
            onClick={() => onCameraTeleport(camInput.x, camInput.y, camInput.z)}
            className="w-full bg-slate-600 hover:bg-slate-700 text-white p-1.5 rounded text-xs flex items-center justify-center gap-1"
          >
             <MapPin size={12} /> پرش به موقعیت
           </button>
           <div className="mt-2 text-center text-xs text-gray-500">
             Current: X:{Math.round(cameraPos.x)} Y:{Math.round(cameraPos.y)} Z:{Math.round(cameraPos.z)}
           </div>
        </Panel>

      </div>
    </>
  );
};

import React, { useState, useCallback, useEffect, Suspense } from 'react';
import { Canvas, useThree } from '@react-three/fiber';
import { OrbitControls, Grid } from '@react-three/drei';
import * as THREE from 'three';
import { GraphNode } from './components/GraphNode';
import { GraphEdge } from './components/GraphEdge';
import { UIOverlay } from './components/UIOverlay';
import { GraphNodeData, GraphEdgeData, AppState, CameraState } from './types';

// Helper component to report camera position back to UI
const CameraReporter: React.FC<{ onUpdate: (pos: THREE.Vector3) => void }> = ({ onUpdate }) => {
  const { camera } = useThree();
  useThree(({ camera }) => {
    // We can use a ref or simplified throttled update if performance is an issue, 
    // but for UI display every frame is okay for this scale.
    onUpdate(camera.position);
  });
  return null;
};

// Helper to move camera programmatically
const CameraController: React.FC<{ targetPos: CameraState | null }> = ({ targetPos }) => {
  const { camera, controls } = useThree();
  useEffect(() => {
    if (targetPos) {
      camera.position.set(targetPos.x, targetPos.y, targetPos.z);
      // @ts-ignore - OrbitControls type definition issues in some versions
      controls?.target?.set(targetPos.x, 0, targetPos.z - 10);
      // @ts-ignore
      controls?.update();
    }
  }, [targetPos, camera, controls]);
  return null;
};

const App: React.FC = () => {
  // --- State ---
  const [nodes, setNodes] = useState<GraphNodeData[]>([]);
  const [edges, setEdges] = useState<GraphEdgeData[]>([]);
  const [appState, setAppState] = useState<AppState>({
    nodes: [],
    edges: [],
    activeId: null,
    activeType: null,
    mode: 'select',
    edgeStartNodeId: null,
  });

  const [cameraPosDisplay, setCameraPosDisplay] = useState({ x: 0, y: 10, z: 20 });
  const [targetCameraPos, setTargetCameraPos] = useState<CameraState | null>(null);
  const [hoverData, setHoverData] = useState<{ label: string; summary: string; full: string } | null>(null);

  // --- Persistence ---
  useEffect(() => {
    const saved = localStorage.getItem('graph_pro_data');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setNodes(parsed.nodes || []);
        setEdges(parsed.edges || []);
      } catch (e) {
        console.error("Failed to load save data", e);
      }
    } else {
      // Init with one node if empty
      handleAddNode();
    }
  }, []);

  useEffect(() => {
    const data = { nodes, edges };
    localStorage.setItem('graph_pro_data', JSON.stringify(data));
  }, [nodes, edges]);

  // --- Actions ---

  const handleAddNode = useCallback(() => {
    const newNode: GraphNodeData = {
      id: crypto.randomUUID(),
      label: `Node ${nodes.length + 1}`,
      summary: "Short summary here...",
      fullContent: "Full RAG content or detailed description goes here.",
      color: "#2196F3",
      size: 1,
      position: [(Math.random() * 10) - 5, 0, (Math.random() * 10) - 5],
    };
    setNodes(prev => [...prev, newNode]);
    // Auto select
    setAppState(prev => ({ ...prev, activeId: newNode.id, activeType: 'node', mode: 'select' }));
  }, [nodes]);

  const handleNodeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();

    setAppState(prev => {
      if (prev.mode === 'select') {
        return { ...prev, activeId: id, activeType: 'node' };
      } 
      else if (prev.mode === 'edge-start') {
        return { ...prev, edgeStartNodeId: id, mode: 'edge-finish' };
      } 
      else if (prev.mode === 'edge-finish') {
        // Create edge
        if (prev.edgeStartNodeId && prev.edgeStartNodeId !== id) {
           const newEdge: GraphEdgeData = {
             id: crypto.randomUUID(),
             fromId: prev.edgeStartNodeId,
             toId: id,
             label: 'Connection',
             color: '#666666'
           };
           setEdges(current => [...current, newEdge]);
           return { ...prev, mode: 'select', activeId: null, activeType: null, edgeStartNodeId: null };
        }
        // Cancel if clicking same node
        return { ...prev, mode: 'select' };
      }
      return prev;
    });
  }, []);

  const handleEdgeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, activeId: id, activeType: 'edge' }));
    }
  }, [appState.mode]);

  const handleBackgroundClick = useCallback(() => {
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, activeId: null, activeType: null }));
    }
  }, [appState.mode]);

  const handleDragNode = useCallback((id: string, newPos: [number, number, number]) => {
    setNodes(prev => prev.map(n => n.id === id ? { ...n, position: newPos } : n));
  }, []);

  const handleUpdateItem = useCallback((id: string, type: 'node' | 'edge', data: any) => {
    if (type === 'node') {
      setNodes(prev => prev.map(n => n.id === id ? { ...n, ...data } : n));
    } else {
      setEdges(prev => prev.map(e => e.id === id ? { ...e, ...data } : e));
    }
  }, []);

  const handleDeleteItem = useCallback(() => {
    const { activeId, activeType } = appState;
    if (!activeId) return;

    if (activeType === 'node') {
      setNodes(prev => prev.filter(n => n.id !== activeId));
      // Delete associated edges
      setEdges(prev => prev.filter(e => e.fromId !== activeId && e.toId !== activeId));
    } else {
      setEdges(prev => prev.filter(e => e.id !== activeId));
    }
    setAppState(prev => ({ ...prev, activeId: null, activeType: null }));
  }, [appState]);

  // --- Import/Export ---
  const handleExport = () => {
    const dataStr = JSON.stringify({ nodes, edges }, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `graph-project-${new Date().toISOString().slice(0,10)}.json`;
    a.click();
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const result = JSON.parse(e.target?.result as string);
        if (result.nodes) setNodes(result.nodes);
        if (result.edges) setEdges(result.edges);
      } catch (err) {
        alert("Invalid JSON file");
      }
    };
    reader.readAsText(file);
  };

  // --- Hover Logic ---
  const handlePointerOver = useCallback((e: any, data: GraphNodeData | GraphEdgeData) => {
    e.stopPropagation();
    if (data.summary || (data as any).fullContent) {
      setHoverData({
        label: data.label,
        summary: (data as any).summary || "",
        full: (data as any).fullContent || ""
      });
    }
  }, []);

  const handlePointerOut = useCallback(() => {
    setHoverData(null);
  }, []);

  return (
    <div className="w-full h-screen relative bg-gray-50">

      <UIOverlay 
        appState={appState}
        nodes={nodes}
        edges={edges}
        cameraPos={cameraPosDisplay}
        onAddNode={handleAddNode}
        onToggleEdgeMode={() => setAppState(prev => ({ 
          ...prev, 
          mode: prev.mode === 'select' ? 'edge-start' : 'select',
          edgeStartNodeId: null
        }))}
        onUpdateItem={handleUpdateItem}
        onDeleteItem={handleDeleteItem}
        onExport={handleExport}
        onImport={handleImport}
        onCameraTeleport={(x, y, z) => setTargetCameraPos({ x, y, z })}
        hoverInfo={hoverData}
      />

      <Canvas shadows camera={{ position: [0, 10, 20], fov: 60 }} onPointerMissed={handleBackgroundClick}>
        <color attach="background" args={['#f0f2f5']} />

        <Suspense fallback={null}>
          <ambientLight intensity={0.6} />
          <pointLight position={[10, 20, 10]} intensity={0.8} castShadow />
          <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" />

          <CameraController targetPos={targetCameraPos} />
          <CameraReporter onUpdate={(pos) => setCameraPosDisplay({ x: pos.x, y: pos.y, z: pos.z })} />
          <OrbitControls makeDefault enableDamping dampingFactor={0.1} />

          {/* Render Nodes */}
          {nodes.map(node => (
            <GraphNode 
              key={node.id} 
              data={node} 
              isSelected={appState.activeId === node.id}
              isEdgeStart={appState.mode === 'edge-finish' && appState.edgeStartNodeId === node.id}
              onClick={handleNodeClick}
              onPointerOver={handlePointerOver}
              onPointerOut={handlePointerOut}
              onDrag={handleDragNode}
              isDraggingEnabled={appState.mode === 'select'}
            />
          ))}

          {/* Render Edges */}
          {edges.map(edge => (
            <GraphEdge 
              key={edge.id}
              data={edge}
              fromNode={nodes.find(n => n.id === edge.fromId)}
              toNode={nodes.find(n => n.id === edge.toId)}
              isSelected={appState.activeId === edge.id}
              onClick={handleEdgeClick}
              onPointerOver={handlePointerOver}
              onPointerOut={handlePointerOut}
            />
          ))}

        </Suspense>
      </Canvas>

      {/* Keyboard Hint */}
      <div className="absolute bottom-4 left-4 text-xs text-gray-400 pointer-events-none">
        Right Click to Rotate • Scroll to Zoom • Left Click to Select/Drag
      </div>
    </div>
  );
};

