      </div>

      {/* --- Footer Hints --- */}
      {uiPanels.hints && (
        <div className="absolute bottom-4 left-4 text-xs text-gray-500 pointer-events-none bg-white/80 backdrop-blur-sm p-2 rounded border border-gray-200 shadow-sm z-10">
