import { GoogleGenAI } from "@google/genai";
import { GraphNodeData, GraphEdgeData } from "../types";

// Initialize Gemini Client
// Note: In a real production build, this key should be secured via a backend proxy.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generatePresentation = async (item: GraphNodeData | GraphEdgeData): Promise<string> => {
  try {
    const model = 'gemini-2.5-flash-image'; // Capable of handling both text and images

    // 1. Prepare Text Context
    let promptText = `
      You are an expert business consultant and presentation designer. 
      I will provide you with data about a specific entity (a startup, concept, or connection) from a knowledge graph.

      **Entity Details:**
      - Label: ${item.label}
      - Summary: ${item.summary}
      - Detailed Content: ${item.fullContent}

      **Your Task:**
      Create a comprehensive, professional HTML presentation for this entity. 
      The HTML should be styled with inline CSS to look modern, clean, and impressive.

      **Structure:**
      1. **Header**: Title (Label) and a catchy tagline based on the summary.
      2. **Executive Summary**: A professional overview.
      3. **Deep Dive**: Elaborate on the "Detailed Content".
      4. **File Analysis**: I have attached files (images/text). Analyze the attached images (logos, diagrams, products) and describe what they show in the context of this entity.
      5. **Conclusion**: A strong closing statement.

      **Style Constraints:**
      - Use a modern font stack (sans-serif).
      - Use a color scheme matching the entity's color: ${item.color}.
      - Return ONLY the raw HTML code (no markdown code blocks like \`\`\`html).
      - Make it responsive and suitable for a modal view.
    `;

    // 2. Prepare Parts (Text + Images)
    const parts: any[] = [{ text: promptText }];

    // 3. Process Attached Files
    if (item.files && item.files.length > 0) {
      item.files.forEach(file => {
        if (file.type.startsWith('image/')) {
          // Add image to the prompt
          // Extract base64 data (remove "data:image/png;base64," prefix)
          const base64Data = file.content.split(',')[1];
          if (base64Data) {
            parts.push({
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            });
          }
        } else if (file.type.startsWith('text/')) {
           // Add text file content to prompt
           // Decode base64 to text
           try {
             const textContent = atob(file.content.split(',')[1]);
             parts.push({ text: `\n\n[Attached File Content: ${file.name}]\n${textContent}` });
           } catch (e) {
             console.warn("Could not decode text file", file.name);
           }
        }
      });
    }

    // 4. Call Gemini
    const response = await ai.models.generateContent({
      model: model,
      contents: { parts: parts }
    });

    return response.text || "<h2>Could not generate presentation.</h2>";

  } catch (error) {
    console.error("AI Generation Error:", error);
    return `
      <div style="color: red; padding: 20px; text-align: center;">
        <h2>Error Generating Presentation</h2>
        <p>Could not connect to AI service. Please ensure API Key is configured.</p>
        <p>${error instanceof Error ? error.message : 'Unknown error'}</p>
      </div>
    `;
  }
};

