export const chatWithAI = async (
  message: string,
  history: ChatMessage[],
  currentItem: GraphNodeData | GraphEdgeData,
  allNodes: GraphNodeData[],
  allEdges: GraphEdgeData[],
  targetLanguage: Language
): Promise<string> => {
  try {
    const langName = targetLanguage === 'fa' ? 'Persian' : 'English';
    const globalContext = getDeepGlobalContext(allNodes, allEdges);
    const historyText = history.slice(-5).map(m => `${m.role}: ${m.text}`).join('\n');
    const { fullTextContext } = getFileParts(currentItem.files);

    const prompt = `
      You are a highly intelligent AI assistant for a Graph Visualization Tool.
      USER LANGUAGE: ${langName}.

      === CURRENT SELECTED ITEM ===
      Label: ${currentItem.label}
      Full Description: ${currentItem.fullContent}
      FILES: ${fullTextContext}

      === GLOBAL KNOWLEDGE BASE ===
      ${globalContext}

      === CHAT HISTORY ===
      ${historyText}

      === QUESTION ===
      "${message}"

      Answer professionally.
    `;

    const response = await ai.models.generateContent({
      model: textModel,
      contents: { parts: [{ text: prompt }] }
    });

    return response.text || "I'm sorry, I couldn't process that.";
  } catch (e) {
    return "Error connecting to AI.";
  }
};

// --- AI ARCHITECT FEATURES ---

export const generateGraphFromFiles = async (
  files: AttachedFile[],
  defs: AIArchitectDefinitions,
  lang: Language
): Promise<{ nodes: any[], edges: any[] }> => {
  try {
    // 1. Prepare file context
    // We take the first 100kb of text to avoid huge context windows for this prototype
    let fileContext = "";
    files.forEach(f => {
       if (f.type.startsWith('text/') || f.name.endsWith('.ts') || f.name.endsWith('.js') || f.name.endsWith('.txt') || f.name.endsWith('.md')) {
         const content = decodeFileContent(f.content).substring(0, 15000);
         fileContext += `\n--- FILE: ${f.name} ---\n${content}\n`;
       }
    });

    const prompt = `
      You are a Graph Architect.
      Task: Analyze the provided project files and construct a graph structure based on the user's definitions.

      USER DEFINITIONS:
      - What is a NODE? ${defs.nodeDefinition}
      - What is an EDGE? ${defs.edgeDefinition}
      - Project Goal: ${defs.projectGoals}

      FILES CONTENT:
      ${fileContext}

      OUTPUT FORMAT:
      Return a JSON object with this schema:
      {
        "nodes": [
          { "label": "string", "summary": "string", "fullContent": "string", "color": "hex_string", "size": number (0.5-2) }
        ],
        "edges": [
          { "fromLabel": "string", "toLabel": "string", "label": "string", "summary": "string" }
        ]
      }

      IMPORTANT:
      - Extract meaningful nodes and edges based strictly on the definitions.
      - If Node definition is "Characters", find characters.
      - If Node definition is "Modules", find code modules.
    `;

    const response = await ai.models.generateContent({
      model: reasoningModel,
      contents: { parts: [{ text: prompt }] },
      config: { responseMimeType: "application/json" }
    });

    const result = JSON.parse(response.text || "{}");
    return result;

  } catch (e) {
    console.error("Architect error:", e);
    return { nodes: [], edges: [] };
  }
};

export const getBrainstormSuggestions = async (
  nodes: GraphNodeData[],
  edges: GraphEdgeData[],
  defs: AIArchitectDefinitions,
  feedback: string
): Promise<AISuggestion[]> => {
  try {
    const globalContext = getDeepGlobalContext(nodes, edges);

    const prompt = `
      You are a Creative Director and System Architect.

      PROJECT CONTEXT:
      - Nodes Definition: ${defs.nodeDefinition}
      - Edges Definition: ${defs.edgeDefinition}
      - GOALS: ${defs.projectGoals}

      CURRENT GRAPH STATE:
      ${globalContext}

      USER FEEDBACK / INSTRUCTION:
      ${feedback || "Analyze the graph and suggest improvements to meet the goals."}

      TASK:
      Provide a list of 3 concrete suggestions to improve the project.

      OUTPUT JSON:
      [
        {
          "id": "unique_id",
          "title": "Short Title",
          "description": "Reasoning why this helps.",
          "type": "add_node" | "add_edge" | "modify_content",
          "data": { ...payload compatible with graph structure... }
        }
      ]

      Payload examples:
      - add_node: { "label": "Name", "summary": "...", "fullContent": "..." }
      - add_edge: { "fromLabel": "A", "toLabel": "B", "label": "Rel" }
      - modify_content: { "nodeLabel": "A", "newFullContent": "..." }
    `;

    const response = await ai.models.generateContent({
      model: reasoningModel,
      contents: { parts: [{ text: prompt }] },
      config: { responseMimeType: "application/json" }
    });

    return JSON.parse(response.text || "[]");
  } catch (e) {
    return [];
  }
};

export const autoCompleteProject = async (
  nodes: GraphNodeData[],
  edges: GraphEdgeData[],
  defs: AIArchitectDefinitions
): Promise<{ modifiedNodes: { id: string, content: string }[], newNodes: any[], newEdges: any[] }> => {
    // This function mimics "Auto Pilot". It reads the graph, and generates extensive content updates for existing nodes
    // and potentially new nodes to "finish" the story/project.

    const globalContext = getDeepGlobalContext(nodes, edges);

    const prompt = `
      You are an AI Co-Author / Auto-Pilot.

      GOAL: Complete the project based on these goals: ${defs.projectGoals}

      DEFINITIONS:
      Nodes: ${defs.nodeDefinition}
      Edges: ${defs.edgeDefinition}

      CURRENT STATE:
      ${globalContext}

      TASK:
      1. Identify missing plot points or code modules.
      2. Write the content for existing nodes to move them towards the goal.
      3. Create new nodes if necessary.

      OUTPUT JSON:
      {
        "modifiedNodes": [
           { "label": "ExistingNodeLabel", "newContent": "The full extended content..." }
        ],
        "newNodes": [
           { "label": "NewNode", "summary": "...", "fullContent": "..." }
        ],
        "newEdges": [
           { "fromLabel": "A", "toLabel": "B", "label": "..." }
        ]
      }
    `;

    try {
      const response = await ai.models.generateContent({
        model: reasoningModel,
        contents: { parts: [{ text: prompt }] },
        config: { responseMimeType: "application/json" }
      });

      const res = JSON.parse(response.text || "{}");

      // Map labels back to IDs for existing nodes
      const mappedModifications = (res.modifiedNodes || []).map((mod: any) => {
         const found = nodes.find(n => n.label === mod.label);
         return found ? { id: found.id, content: mod.newContent } : null;
      }).filter((x: any) => x !== null);

      return {
        modifiedNodes: mappedModifications,
        newNodes: res.newNodes || [],
        newEdges: res.newEdges || []
      };

    } catch (e) {
      console.error(e);
      return { modifiedNodes: [], newNodes: [], newEdges: [] };
    }
}

import React, { useState, useRef } from 'react';
import { X, Upload, BrainCircuit, Play, Check, ThumbsDown, ArrowRight, Loader2, FolderOpen, FileText } from 'lucide-react';
import { AIArchitectDefinitions, AISuggestion, AttachedFile, Language, GraphNodeData, GraphEdgeData } from '../types';
import { translations, getDir } from '../utils/translations';
import { generateGraphFromFiles, getBrainstormSuggestions, autoCompleteProject } from '../services/ai';

interface AIArchitectModalProps {
  isOpen: boolean;
  onClose: () => void;
  lang: Language;
  nodes: GraphNodeData[];
  edges: GraphEdgeData[];
  onApplyGraph: (newNodes: any[], newEdges: any[]) => void;
  onApplyChanges: (suggestions: any) => void;
}

export const AIArchitectModal: React.FC<AIArchitectModalProps> = ({
  isOpen, onClose, lang, nodes, edges, onApplyGraph, onApplyChanges
}) => {
  const [activeTab, setActiveTab] = useState<1 | 2 | 3>(1);
  const [defs, setDefs] = useState<AIArchitectDefinitions>({
    nodeDefinition: '',
    edgeDefinition: '',
    projectGoals: ''
  });
  const [uploadedFiles, setUploadedFiles] = useState<AttachedFile[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  // Brainstorm state
  const [suggestions, setSuggestions] = useState<AISuggestion[]>([]);
  const [feedback, setFeedback] = useState('');

  const t = translations[lang].architect;
  const dir = getDir(lang);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleFolderUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const filesArray: AttachedFile[] = [];
      Array.from(e.target.files).forEach(file => {
        // Simple filter for text/code files
        if (file.type.startsWith('text/') || file.name.match(/\.(js|ts|tsx|jsx|json|md|txt|py|java|cs)$/)) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                filesArray.push({
                    id: crypto.randomUUID(),
                    name: file.webkitRelativePath || file.name,
                    type: file.type || 'text/plain',
                    content: ev.target?.result as string
                });
                if (filesArray.length === e.target.files?.length) {
                    setUploadedFiles(filesArray);
                }
            };
            reader.readAsDataURL(file);
        }
      });
      // In a real async scenario we'd wait better, but for prototype:
      setTimeout(() => setUploadedFiles(filesArray), 1000);
    }
  };

  const handleBuildGraph = async () => {
    setIsProcessing(true);
    const result = await generateGraphFromFiles(uploadedFiles, defs, lang);
    onApplyGraph(result.nodes, result.edges);
    setIsProcessing(false);
    onClose();
  };

  const handleGetSuggestions = async () => {
    setIsProcessing(true);
    const results = await getBrainstormSuggestions(nodes, edges, defs, feedback);
    setSuggestions(results.map(r => ({ ...r, status: 'pending' })));
    setIsProcessing(false);
  };

  const handleAutoComplete = async () => {
    setIsProcessing(true);
    const result = await autoCompleteProject(nodes, edges, defs);
    onApplyChanges(result); // Applies content updates to shadow files
    setIsProcessing(false);
    onClose();
  };

  const handleAcceptSuggestion = (s: AISuggestion) => {
    // Logic to apply specific suggestion
    if (s.type === 'add_node') onApplyGraph([s.data], []);
    if (s.type === 'add_edge') onApplyGraph([], [s.data]);
    if (s.type === 'modify_content') {
       onApplyChanges({ modifiedNodes: [{ id: nodes.find(n => n.label === s.data.nodeLabel)?.id, content: s.data.newFullContent }] });
    }
    setSuggestions(prev => prev.filter(x => x.id !== s.id));
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4" dir={dir}>
      <div className="bg-white w-full max-w-4xl h-[80vh] rounded-xl shadow-2xl flex flex-col overflow-hidden">

        {/* Header */}
        <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
          <div className="flex items-center gap-2 font-bold text-lg">
            <BrainCircuit className="text-purple-400" />
            {t.title}
          </div>
          <button onClick={onClose}><X /></button>
        </div>

        {/* Tabs */}
        <div className="flex border-b bg-gray-50">
          <button 
            onClick={() => setActiveTab(1)}
            className={`flex-1 py-3 px-4 font-medium transition-colors ${activeTab === 1 ? 'bg-white border-b-2 border-purple-500 text-purple-700' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            {t.tabDef}
          </button>
          <button 
            onClick={() => setActiveTab(2)}
            className={`flex-1 py-3 px-4 font-medium transition-colors ${activeTab === 2 ? 'bg-white border-b-2 border-purple-500 text-purple-700' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            {t.tabUpload}
          </button>
          <button 
            onClick={() => setActiveTab(3)}
            className={`flex-1 py-3 px-4 font-medium transition-colors ${activeTab === 3 ? 'bg-white border-b-2 border-purple-500 text-purple-700' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            {t.tabBrain}
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">

          {/* TAB 1: DEFINITIONS */}
          {activeTab === 1 && (
            <div className="space-y-6 max-w-2xl mx-auto">
              <div>
                <label className="block font-bold text-gray-700 mb-2">{t.nodeDefLabel}</label>
                <input 
                  type="text" 
                  className="w-full border rounded p-3 focus:outline-purple-500 bg-gray-50"
                  placeholder={t.nodeDefPlace}
                  value={defs.nodeDefinition}
                  onChange={e => setDefs({...defs, nodeDefinition: e.target.value})}
                />
              </div>
              <div>
                <label className="block font-bold text-gray-700 mb-2">{t.edgeDefLabel}</label>
                <input 
                  type="text" 
                  className="w-full border rounded p-3 focus:outline-purple-500 bg-gray-50"
                  placeholder={t.edgeDefPlace}
                  value={defs.edgeDefinition}
                  onChange={e => setDefs({...defs, edgeDefinition: e.target.value})}
                />
              </div>
              <div>
                <label className="block font-bold text-gray-700 mb-2">{t.goalsLabel}</label>
                <textarea 
                  className="w-full border rounded p-3 focus:outline-purple-500 bg-gray-50 h-32"
                  placeholder={t.goalsPlace}
                  value={defs.projectGoals}
                  onChange={e => setDefs({...defs, projectGoals: e.target.value})}
                />
              </div>
              <div className="flex justify-end">
                <button 
                  onClick={() => setActiveTab(2)}
                  className="bg-purple-600 text-white px-6 py-2 rounded-lg hover:bg-purple-700 flex items-center gap-2"
                >
                  {translations[lang].architect.tabUpload} <ArrowRight size={16} />
                </button>
              </div>
            </div>
          )}

          {/* TAB 2: UPLOAD */}
          {activeTab === 2 && (
            <div className="flex flex-col items-center justify-center h-full space-y-6">
              <div 
                className="border-2 border-dashed border-gray-300 rounded-xl p-10 w-full max-w-xl flex flex-col items-center justify-center bg-gray-50 hover:bg-purple-50 transition-colors cursor-pointer"
                onClick={() => fileInputRef.current?.click()}
              >
                <FolderOpen size={48} className="text-purple-400 mb-4" />
                <h3 className="text-lg font-bold text-gray-700">{t.uploadLabel}</h3>
                <p className="text-sm text-gray-500 text-center mt-2">{t.uploadNote}</p>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  // @ts-ignore - webkitdirectory is non-standard but supported
                  webkitdirectory="" 
                  directory="" 
                  multiple 
                  onChange={handleFolderUpload}
                />
              </div>

              {uploadedFiles.length > 0 && (
                 <div className="w-full max-w-xl">
                   <div className="font-bold text-sm text-green-600 mb-2 flex items-center gap-2">
                     <Check size={16} /> {uploadedFiles.length} files prepared.
                   </div>
                   <button 
                    onClick={handleBuildGraph}
                    disabled={isProcessing}
                    className="w-full bg-purple-600 text-white py-3 rounded-lg font-bold hover:bg-purple-700 disabled:opacity-50 flex justify-center items-center gap-2"
                   >
                     {isProcessing ? <Loader2 className="animate-spin" /> : <Play size={20} />}
                     {isProcessing ? t.processing : t.uploadBtn}
                   </button>
                 </div>
              )}
            </div>
          )}

          {/* TAB 3: BRAINSTORM */}
          {activeTab === 3 && (
            <div className="flex flex-col h-full gap-4">
               <div className="bg-yellow-50 border border-yellow-200 p-3 rounded-lg text-xs text-yellow-800 flex items-center gap-2">
                 <FileText size={16} />
                 {t.shadowCopyNote}
               </div>

               <div className="flex gap-4">
                 <div className="flex-1 bg-gray-50 p-4 rounded-lg flex flex-col gap-3">
                   <h3 className="font-bold text-gray-700">{t.brainMode}</h3>
                   <textarea 
                     className="w-full border rounded p-2 text-sm h-24"
                     placeholder={t.feedbackPlace}
                     value={feedback}
                     onChange={e => setFeedback(e.target.value)}
                   />
                   <div className="flex gap-2">
                     <button 
                       onClick={handleGetSuggestions} 
                       disabled={isProcessing}
                       className="flex-1 bg-blue-600 text-white py-2 rounded hover:bg-blue-700 flex items-center justify-center gap-2 text-sm"
                     >
                        {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <BrainCircuit size={16} />}
                        {t.getSuggestions}
                     </button>
                     <button 
                        onClick={handleAutoComplete}
                        disabled={isProcessing}
                        className="flex-1 bg-purple-600 text-white py-2 rounded hover:bg-purple-700 flex items-center justify-center gap-2 text-sm"
                     >
                        {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <Play size={16} />}
                        {t.autoComplete}
                     </button>
                   </div>
                 </div>
               </div>

               {/* Suggestions List */}
               <div className="flex-1 overflow-y-auto space-y-3">
                 {suggestions.map(s => (
                   <div key={s.id} className="border rounded-lg p-4 bg-white shadow-sm flex justify-between items-start gap-4 hover:shadow-md transition-shadow">
                      <div>
                        <div className="font-bold text-purple-700 flex items-center gap-2">
                          <span className="bg-purple-100 text-[10px] px-2 py-0.5 rounded uppercase">{s.type.replace('_', ' ')}</span>
                          {s.title}
                        </div>
                        <p className="text-sm text-gray-600 mt-1">{s.description}</p>
                      </div>
                      <div className="flex gap-2 shrink-0">
                        <button onClick={() => handleAcceptSuggestion(s)} className="text-green-600 hover:bg-green-50 p-1 rounded" title={t.apply}><Check size={20}/></button>
                        <button onClick={() => setSuggestions(prev => prev.filter(x => x.id !== s.id))} className="text-red-500 hover:bg-red-50 p-1 rounded" title={t.reject}><ThumbsDown size={20}/></button>
                      </div>
                   </div>
                 ))}
                 {suggestions.length === 0 && !isProcessing && (
                   <div className="text-center text-gray-400 mt-10 italic">
                     Ready for brainstorming...
                   </div>
                 )}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

