// Keyboard Control Component for Arrow navigation ONLY
const KeyboardControls = () => {
  const { camera, controls } = useThree();
  const [keys, setKeys] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => setKeys((k) => ({ ...k, [e.code]: true }));
    const handleKeyUp = (e: KeyboardEvent) => setKeys((k) => ({ ...k, [e.code]: false }));

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useFrame((state, delta) => {
    // @ts-ignore
    if (!controls || !controls.enabled) return;

    const speed = 20 * delta; 
    const moveVector = new THREE.Vector3();

    const forward = new THREE.Vector3();
    camera.getWorldDirection(forward);
    forward.y = 0;
    forward.normalize();

    const right = new THREE.Vector3();
    right.crossVectors(forward, new THREE.Vector3(0, 1, 0));
    right.normalize();

    // Removed WASD to prevent typing conflict
    if (keys['ArrowUp']) moveVector.add(forward.multiplyScalar(speed));
    if (keys['ArrowDown']) moveVector.add(forward.multiplyScalar(-speed));
    if (keys['ArrowRight']) moveVector.add(right.multiplyScalar(-speed));
    if (keys['ArrowLeft']) moveVector.add(right.multiplyScalar(speed));

    if (moveVector.lengthSq() > 0) {
      camera.position.add(moveVector);
      // @ts-ignore
      if (controls.target) {
         // @ts-ignore
         controls.target.add(moveVector);
      }
    }
  });

  return null;
};

const CameraReporter: React.FC<{ onUpdate: (pos: THREE.Vector3) => void }> = ({ onUpdate }) => {
  const { camera } = useThree();
  useThree(({ camera }) => {
    onUpdate(camera.position);
  });
  return null;
};

const CameraController: React.FC<{ targetPos: CameraState | null }> = ({ targetPos }) => {
  const { camera, controls } = useThree();
  useEffect(() => {
    if (targetPos) {
      camera.position.set(targetPos.x, targetPos.y, targetPos.z);
      // @ts-ignore
      controls?.target?.set(targetPos.x, 0, targetPos.z - 10);
      // @ts-ignore
      controls?.update();
    }
  }, [targetPos, camera, controls]);
  return null;
};

const App: React.FC = () => {
  const [nodes, setNodes] = useState<GraphNodeData[]>([]);
  const [edges, setEdges] = useState<GraphEdgeData[]>([]);
  const [appState, setAppState] = useState<AppState>({
    nodes: [],
    edges: [],
    selectedIds: [],
    activeType: null,
    mode: 'select',
    edgeStartNodeId: null,
    appLanguage: 'fa' 
  });

  // History Stacks for Undo/Redo
  const [history, setHistory] = useState<{nodes: GraphNodeData[], edges: GraphEdgeData[]}[]>([]);
  const [future, setFuture] = useState<{nodes: GraphNodeData[], edges: GraphEdgeData[]}[]>([]);

  const [cameraPosDisplay, setCameraPosDisplay] = useState({ x: 0, y: 10, z: 20 });
  const [targetCameraPos, setTargetCameraPos] = useState<CameraState | null>(null);
  const [hoverData, setHoverData] = useState<{ label: string; summary: string; full: string } | null>(null);

  const [uiPanels, setUiPanels] = useState<UIPanelsState>({
    tools: true,
    properties: true,
    camera: true,
    hints: true,
    filePanel: false 
  });

  const [presentationMode, setPresentationMode] = useState<{ 
    isOpen: boolean; 
    content: string; 
    isLoading: boolean;
    activeFiles: AttachedFile[]; 
    targetLanguage: Language;
    activeItemId: string | null;
  }>({
    isOpen: false,
    content: '',
    isLoading: false,
    activeFiles: [],
    targetLanguage: 'fa',
    activeItemId: null
  });

  // --- History Management ---
  const saveHistory = useCallback(() => {
    setHistory(prev => {
      // Optimization: Optionally check if the new state is identical to the last to avoid dups
      // But for simplicity and correctness with "pre-action" saving, we just push.
      return [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }];
    });
    setFuture([]); // Clear redo stack on new action
  }, [nodes, edges]);

  const undo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    const newHistory = history.slice(0, -1);

    setFuture(prev => [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }]);
    setNodes(previous.nodes);
    setEdges(previous.edges);
    setHistory(newHistory);
  }, [history, nodes, edges]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[future.length - 1];
    const newFuture = future.slice(0, -1);

    setHistory(prev => [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }]);
    setNodes(next.nodes);
    setEdges(next.edges);
    setFuture(newFuture);
  }, [future, nodes, edges]);

  // Keyboard Shortcuts for Undo/Redo
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
        if (e.shiftKey) {
          redo();
        } else {
          undo();
        }
      } else if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  useEffect(() => {
    const saved = localStorage.getItem('graph_pro_data');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setNodes(parsed.nodes || []);
        setEdges(parsed.edges || []);
      } catch (e) {
        console.error("Failed to load save data", e);
      }
    } else {
      handleAddNode();
    }
  }, []);

  useEffect(() => {
    const data = { nodes, edges };
    localStorage.setItem('graph_pro_data', JSON.stringify(data));
  }, [nodes, edges]);

  useEffect(() => {
    document.documentElement.dir = getDir(appState.appLanguage);
    document.documentElement.lang = appState.appLanguage;
  }, [appState.appLanguage]);

  const handleAddNode = useCallback(() => {
    saveHistory(); // Snapshot
    const newNode: GraphNodeData = {
      id: crypto.randomUUID(),
      label: `Node ${nodes.length + 1}`,
      summary: "Short summary...",
      fullContent: "Detailed description...",
      color: "#2196F3",
      size: 1,
      position: [(Math.random() * 10) - 5, 0, (Math.random() * 10) - 5],
      files: []
    };
    setNodes(prev => [...prev, newNode]);
    setAppState(prev => ({ ...prev, selectedIds: [newNode.id], activeType: 'node', mode: 'select' }));
  }, [nodes, saveHistory]);

  const handleNodeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();
    setAppState(prev => {
      if (prev.mode === 'select') {
        return { ...prev, selectedIds: [id], activeType: 'node' };
      } 
      else if (prev.mode === 'edge-start') {
        return { ...prev, edgeStartNodeId: id, mode: 'edge-finish' };
      } 
      else if (prev.mode === 'edge-finish') {
        if (prev.edgeStartNodeId && prev.edgeStartNodeId !== id) {
           saveHistory(); // Snapshot before creating edge
           const newEdge: GraphEdgeData = {
             id: crypto.randomUUID(),
             fromId: prev.edgeStartNodeId,
             toId: id,
             label: 'Connection',
             color: '#666666',
             size: 0.1,
             summary: "Connection...",
             fullContent: "Description...",
             files: [],
             direction: 'bidirectional'
           };
           setEdges(current => [...current, newEdge]);
           return { ...prev, mode: 'select', selectedIds: [], activeType: null, edgeStartNodeId: null };
        }
        return { ...prev, mode: 'select' };
      }
      return prev;
    });
  }, [saveHistory]);

  const handleEdgeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, selectedIds: [id], activeType: 'edge' }));
    }
  }, [appState.mode]);

  const handleBackgroundClick = useCallback(() => {
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, selectedIds: [], activeType: null }));
    }
  }, [appState.mode]);

  // --- Image Save Handler (for Generated Images) ---
  const handleAddFile = useCallback((file: AttachedFile, itemId: string) => {
    saveHistory();
    // Save generated image to node/edge state
    const targetNode = nodes.find(n => n.id === itemId);
    if (targetNode) {
        setNodes(prev => prev.map(n => n.id === itemId ? { ...n, files: [...n.files, file] } : n));
        return;
    }
    const targetEdge = edges.find(e => e.id === itemId);
    if (targetEdge) {
        setEdges(prev => prev.map(e => e.id === itemId ? { ...e, files: [...e.files, file] } : e));
    }
  }, [nodes, edges, saveHistory]);

  const handleRemoveFile = useCallback((fileId: string, itemId: string) => {
    saveHistory();
    const targetNode = nodes.find(n => n.id === itemId);
    if (targetNode) {
        setNodes(prev => prev.map(n => n.id === itemId ? { ...n, files: n.files.filter(f => f.id !== fileId) } : n));
        return;
    }
    const targetEdge = edges.find(e => e.id === itemId);
    if (targetEdge) {
        setEdges(prev => prev.map(e => e.id === itemId ? { ...e, files: e.files.filter(f => f.id !== fileId) } : e));
    }
  }, [nodes, edges, saveHistory]);

  // --- AI Presentation Handlers ---
  const openPresentation = (content: string, item: GraphNodeData | GraphEdgeData, isLoading = false) => {
     setPresentationMode({
        isOpen: true,
        content: content,
        isLoading: isLoading,
        activeFiles: item.files || [],
        targetLanguage: appState.appLanguage,
        activeItemId: item.id
      });
  };

  const handleDoubleClick = useCallback(async (e: any, id: string) => {
    e.stopPropagation();
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      openPresentation('', target, true);
      const htmlContent = await generatePresentation(target, appState.appLanguage);
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  }, [nodes, edges, appState.appLanguage]);

  const handleCakePresentation = useCallback(async () => {
    const id = appState.selectedIds[0];
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      openPresentation('', target, true);
      const htmlContent = await generateCakePresentation(target, appState.appLanguage);
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  }, [nodes, edges, appState.selectedIds, appState.appLanguage]);

  const handleSmartGuide = useCallback(async () => {
    const id = appState.selectedIds[0];
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      openPresentation('', target, true);
      const htmlContent = await generateSmartGuide(target, nodes, edges, appState.appLanguage);
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  }, [nodes, edges, appState.selectedIds, appState.appLanguage]);

  const regeneratePresentation = async (lang: Language) => {
    const id = presentationMode.activeItemId;
    if (!id) return;
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      setPresentationMode(prev => ({ ...prev, isLoading: true, targetLanguage: lang }));
      const htmlContent = await generatePresentation(target, lang);
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  };

  const handleDragNode = useCallback((id: string, newPos: [number, number, number]) => {
    // Note: saveHistory is triggered by onDragStart in GraphNode component
    setNodes(prev => {
      const draggedNode = prev.find(n => n.id === id);
      if (!draggedNode) return prev;
      const dx = newPos[0] - draggedNode.position[0];
      const dy = newPos[1] - draggedNode.position[1];
      const dz = newPos[2] - draggedNode.position[2];

      if (appState.selectedIds.includes(id)) {
        return prev.map(n => {
          if (appState.selectedIds.includes(n.id)) {
             return { ...n, position: [n.position[0] + dx, n.position[1] + dy, n.position[2] + dz] };
          }
          return n;
        });
      }
      return prev.map(n => n.id === id ? { ...n, position: newPos } : n);
    });
  }, [appState.selectedIds]);

  const handleUpdateItem = useCallback((id: string, type: 'node' | 'edge', data: any) => {
    // Note: saveHistory is triggered by onPushHistory (onFocus/onClick) in UIOverlay
    const targetIds = appState.selectedIds.includes(id) ? appState.selectedIds : [id];
    if (type === 'node') {
      setNodes(prev => prev.map(n => targetIds.includes(n.id) ? { ...n, ...data } : n));
    } else {
      setEdges(prev => prev.map(e => targetIds.includes(e.id) ? { ...e, ...data } : e));
    }
  }, [appState.selectedIds]);

  const handleFileUpload = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      saveHistory();
      const result = e.target?.result as string; 
      const newFile: AttachedFile = {
        id: crypto.randomUUID(),
        name: file.name,
        type: file.type,
        content: result
      };
      const { selectedIds, activeType } = appState;
      if (activeType === 'node') {
        setNodes(prev => prev.map(n => selectedIds.includes(n.id) ? { ...n, files: [...(n.files || []), newFile] } : n));
      } else if (activeType === 'edge') {
        setEdges(prev => prev.map(e => selectedIds.includes(e.id) ? { ...e, files: [...(e.files || []), newFile] } : e));
      }
    };
    reader.readAsDataURL(file);
  }, [appState, saveHistory]);

  const handleDeleteFile = useCallback((fileId: string) => {
    saveHistory();
    const { selectedIds, activeType } = appState;
    if (activeType === 'node') {
      setNodes(prev => prev.map(n => selectedIds.includes(n.id) ? { ...n, files: n.files?.filter(f => f.id !== fileId) || [] } : n));
    } else if (activeType === 'edge') {
      setEdges(prev => prev.map(e => selectedIds.includes(e.id) ? { ...e, files: e.files?.filter(f => f.id !== fileId) || [] } : e));
    }
  }, [appState, saveHistory]);

  const handleDeleteItem = useCallback(() => {
    saveHistory();
    const { selectedIds, activeType } = appState;
    if (selectedIds.length === 0) return;
    if (activeType === 'node') {
      setNodes(prev => prev.filter(n => !selectedIds.includes(n.id)));
      setEdges(prev => prev.filter(e => !selectedIds.includes(e.fromId) && !selectedIds.includes(e.toId)));
    } else {
      setEdges(prev => prev.filter(e => !selectedIds.includes(e.id)));
    }
    setAppState(prev => ({ ...prev, selectedIds: [], activeType: null }));
  }, [appState, saveHistory]);

  const handleSelectSameColor = useCallback(() => {
    const { selectedIds, activeType } = appState;
    if (selectedIds.length === 0 || !activeType) return;
    let refColor = activeType === 'node' ? nodes.find(n => n.id === selectedIds[0])?.color : edges.find(e => e.id === selectedIds[0])?.color;
    if (!refColor) return;
    let newSelection = activeType === 'node' ? nodes.filter(n => n.color === refColor).map(n => n.id) : edges.filter(e => e.color === refColor).map(e => e.id);
    setAppState(prev => ({ ...prev, selectedIds: newSelection }));
  }, [appState, nodes, edges]);

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ nodes, edges }, null, 2)], { type: "application/json" });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `graph-project-${new Date().toISOString().slice(0,10)}.json`;
    a.click();
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        saveHistory();
        const result = JSON.parse(e.target?.result as string);
        if (result.nodes) setNodes(result.nodes);
        if (result.edges) setEdges(result.edges);
      } catch (err) { alert("Invalid JSON"); }
    };
    reader.readAsText(file);
  };

  // AI Architect: Apply Graph Structure from Files
  const handleApplyGraphFromAI = useCallback((newNodesRaw: any[], newEdgesRaw: any[]) => {
    saveHistory();

    // Map raw AI JSON to GraphNodeData
    const mappedNodes: GraphNodeData[] = newNodesRaw.map((n, idx) => ({
       id: crypto.randomUUID(),
       label: n.label,
       summary: n.summary || "",
       fullContent: n.fullContent || "",
       color: n.color || `hsl(${Math.random() * 360}, 70%, 50%)`,
       size: n.size || 1,
       position: [(Math.random() * 20) - 10, (Math.random() * 10) - 5, (Math.random() * 20) - 10], // Random pos for now
       files: []
    }));

    // Map raw AI JSON to GraphEdgeData
    const mappedEdges: GraphEdgeData[] = newEdgesRaw.map(e => {
       const fromNode = mappedNodes.find(n => n.label === e.fromLabel);
       const toNode = mappedNodes.find(n => n.label === e.toLabel);
       if (fromNode && toNode) {
         return {
           id: crypto.randomUUID(),
           fromId: fromNode.id,
           toId: toNode.id,
           label: e.label,
           color: '#888',
           size: 0.2,
           summary: e.summary || "",
           fullContent: "",
           files: [],
           direction: 'bidirectional'
         };
       }
       return null;
    }).filter(e => e !== null) as GraphEdgeData[];

    setNodes(mappedNodes);
    setEdges(mappedEdges);
  }, [saveHistory]);

  // AI Architect: Apply Changes (Shadow Copy logic)
  const handleApplyChangesFromAI = useCallback((changes: { modifiedNodes: {id: string, content: string}[], newNodes: any[], newEdges: any[] }) => {
     saveHistory();

     // 1. Handle Content Updates as Shadow Files
     if (changes.modifiedNodes && changes.modifiedNodes.length > 0) {
        setNodes(prev => prev.map(node => {
           const mod = changes.modifiedNodes.find(m => m.id === node.id);
           if (mod) {
             // Create a Shadow File instead of overwriting content directly
             const shadowFile: AttachedFile = {
               id: crypto.randomUUID(),
               name: `AI_Generated_Content_${Date.now()}.txt`,
               type: 'text/plain',
               content: `data:text/plain;base64,${btoa(unescape(encodeURIComponent(mod.content)))}`,
               isAiGenerated: true
             };
             return { ...node, files: [...node.files, shadowFile] };
           }
           return node;
        }));
     }

     // 2. Handle New Nodes
     if (changes.newNodes && changes.newNodes.length > 0) {
        const addedNodes: GraphNodeData[] = changes.newNodes.map(n => ({
          id: crypto.randomUUID(),
          label: n.label,
          summary: n.summary || "AI Generated",
          fullContent: n.fullContent || "",
          color: '#A020F0', // Purple for AI nodes
          size: 1,
          position: [(Math.random() * 20) - 10, 0, (Math.random() * 20) - 10],
          files: []
        }));
        setNodes(prev => [...prev, ...addedNodes]);
     }

     // 3. Handle New Edges (Note: this is complex as it needs to link to potentially new nodes)
     // For this prototype, we'll skip complex edge linking for auto-pilot to avoid ID mismatch errors,
     // or only link if nodes exist.
  }, [saveHistory]);

  const handlePointerOver = useCallback((e: any, data: GraphNodeData | GraphEdgeData) => {
    e.stopPropagation();
    if ('summary' in data) {
      setHoverData({ label: data.label, summary: data.summary || "", full: data.fullContent || "" });
    }
  }, []);

  const handlePointerOut = useCallback(() => { setHoverData(null); }, []);

  return (
    <div className={`w-full h-screen relative bg-gray-50 flex flex-col font-sans`}>
      <UIOverlay 
        appState={appState}
        nodes={nodes}
        edges={edges}
        cameraPos={cameraPosDisplay}
        uiPanels={uiPanels}
        setUiPanels={setUiPanels}
        setAppState={setAppState}
        onAddNode={handleAddNode}
        onToggleEdgeMode={() => setAppState(prev => ({ ...prev, mode: prev.mode === 'select' ? 'edge-start' : 'select', edgeStartNodeId: null }))}
        onUpdateItem={handleUpdateItem}
        onDeleteItem={handleDeleteItem}
        onExport={handleExport}
        onImport={handleImport}
        onCameraTeleport={(x, y, z) => setTargetCameraPos({ x, y, z })}
        hoverInfo={hoverData}
        onSelectSameColor={handleSelectSameColor}
        onFileUpload={handleFileUpload}
        onDeleteFile={handleDeleteFile}
        presentationMode={presentationMode}
        setPresentationMode={setPresentationMode}
        onRegeneratePresentation={regeneratePresentation}
        onCakePresentation={handleCakePresentation}
        onSmartGuide={handleSmartGuide}
        onAddFile={handleAddFile} 
        onRemoveFile={handleRemoveFile}
        onUndo={undo}
        onRedo={redo}
        canUndo={history.length > 0}
        canRedo={future.length > 0}
        onPushHistory={saveHistory}
        onApplyGraphFromAI={handleApplyGraphFromAI}
        onApplyChangesFromAI={handleApplyChangesFromAI}
      />

      <div className="flex-1 relative mt-12"> 
        <Canvas shadows camera={{ position: [0, 10, 20], fov: 60 }} onPointerMissed={handleBackgroundClick}>
          <color attach="background" args={['#f0f2f5']} />
          <Suspense fallback={null}>
            <ambientLight intensity={0.6} />
            <pointLight position={[10, 20, 10]} intensity={0.8} castShadow />
            <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" />
            <CameraController targetPos={targetCameraPos} />
            <CameraReporter onUpdate={(pos) => setCameraPosDisplay({ x: pos.x, y: pos.y, z: pos.z })} />
            <KeyboardControls />
            <OrbitControls makeDefault enableDamping dampingFactor={0.1} mouseButtons={{ LEFT: undefined, MIDDLE: THREE.MOUSE.PAN, RIGHT: THREE.MOUSE.ROTATE }} />
            {nodes.map(node => (
              <GraphNode 
                key={node.id} 
                data={node} 
                isSelected={appState.selectedIds.includes(node.id)}
                isEdgeStart={appState.mode === 'edge-finish' && appState.edgeStartNodeId === node.id}
                onClick={handleNodeClick}
                onDoubleClick={handleDoubleClick}
                onPointerOver={handlePointerOver}
                onPointerOut={handlePointerOut}
                onDrag={handleDragNode}
                onDragStart={saveHistory} // Trigger save on drag start
                isDraggingEnabled={appState.mode === 'select'}
              />
            ))}
            {edges.map(edge => (
              <GraphEdge 
                key={edge.id}
                data={edge}
                fromNode={nodes.find(n => n.id === edge.fromId)}
                toNode={nodes.find(n => n.id === edge.toId)}
                isSelected={appState.selectedIds.includes(edge.id)}
                onClick={handleEdgeClick}
                onDoubleClick={handleDoubleClick}
                onPointerOver={handlePointerOver}
                onPointerOut={handlePointerOut}
              />
            ))}
          </Suspense>
        </Canvas>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { X, Upload, BrainCircuit, Play, Check, ThumbsDown, ArrowRight, Loader2, FolderOpen, FileText } from 'lucide-react';
import { AIArchitectDefinitions, AISuggestion, AttachedFile, Language, GraphNodeData, GraphEdgeData } from '../types';
import { translations, getDir } from '../utils/translations';
import { generateGraphFromFiles, getBrainstormSuggestions, autoCompleteProject } from '../services/ai';

interface AIArchitectModalProps {
  isOpen: boolean;
  onClose: () => void;
  lang: Language;
  nodes: GraphNodeData[];
  edges: GraphEdgeData[];
  onApplyGraph: (newNodes: any[], newEdges: any[]) => void;
  onApplyChanges: (suggestions: any) => void;
}

export const AIArchitectModal: React.FC<AIArchitectModalProps> = ({
  isOpen, onClose, lang, nodes, edges, onApplyGraph, onApplyChanges
}) => {
  const [activeTab, setActiveTab] = useState<1 | 2 | 3>(1);
  const [defs, setDefs] = useState<AIArchitectDefinitions>({
    nodeDefinition: '',
    edgeDefinition: '',
    projectGoals: ''
  });
  const [uploadedFiles, setUploadedFiles] = useState<AttachedFile[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  // Brainstorm state
  const [suggestions, setSuggestions] = useState<AISuggestion[]>([]);
  const [feedback, setFeedback] = useState('');

  const t = translations[lang].architect;
  const dir = getDir(lang);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleFolderUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const filesArray: AttachedFile[] = [];
      Array.from(e.target.files).forEach((file: any) => {
        // Simple filter for text/code files
        if (file.type.startsWith('text/') || file.name.match(/\.(js|ts|tsx|jsx|json|md|txt|py|java|cs)$/)) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                filesArray.push({
                    id: crypto.randomUUID(),
                    name: file.webkitRelativePath || file.name,
                    type: file.type || 'text/plain',
                    content: ev.target?.result as string
                });
                if (filesArray.length === e.target.files?.length) {
                    setUploadedFiles(filesArray);
                }
            };
            reader.readAsDataURL(file);
        }
      });
      // In a real async scenario we'd wait better, but for prototype:
      setTimeout(() => setUploadedFiles(filesArray), 1000);
    }
  };

  const handleBuildGraph = async () => {
    setIsProcessing(true);
    const result = await generateGraphFromFiles(uploadedFiles, defs, lang);
    onApplyGraph(result.nodes, result.edges);
    setIsProcessing(false);
    onClose();
  };

  const handleGetSuggestions = async () => {
    setIsProcessing(true);
    const results = await getBrainstormSuggestions(nodes, edges, defs, feedback);
    setSuggestions(results.map(r => ({ ...r, status: 'pending' })));
    setIsProcessing(false);
  };

  const handleAutoComplete = async () => {
    setIsProcessing(true);
    const result = await autoCompleteProject(nodes, edges, defs);
    onApplyChanges(result); // Applies content updates to shadow files
    setIsProcessing(false);
    onClose();
  };

  const handleAcceptSuggestion = (s: AISuggestion) => {
    // Logic to apply specific suggestion
    if (s.type === 'add_node') onApplyGraph([s.data], []);
    if (s.type === 'add_edge') onApplyGraph([], [s.data]);
    if (s.type === 'modify_content') {
       onApplyChanges({ modifiedNodes: [{ id: nodes.find(n => n.label === s.data.nodeLabel)?.id, content: s.data.newFullContent }] });
    }
    setSuggestions(prev => prev.filter(x => x.id !== s.id));
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4" dir={dir}>
      <div className="bg-white w-full max-w-4xl h-[80vh] rounded-xl shadow-2xl flex flex-col overflow-hidden">

        {/* Header */}
        <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
          <div className="flex items-center gap-2 font-bold text-lg">
            <BrainCircuit className="text-purple-400" />
            {t.title}
          </div>
          <button onClick={onClose}><X /></button>
        </div>

        {/* Tabs */}
        <div className="flex border-b bg-gray-50">
          <button 
            onClick={() => setActiveTab(1)}
            className={`flex-1 py-3 px-4 font-medium transition-colors ${activeTab === 1 ? 'bg-white border-b-2 border-purple-500 text-purple-700' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            {t.tabDef}
          </button>
          <button 
            onClick={() => setActiveTab(2)}
            className={`flex-1 py-3 px-4 font-medium transition-colors ${activeTab === 2 ? 'bg-white border-b-2 border-purple-500 text-purple-700' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            {t.tabUpload}
          </button>
          <button 
            onClick={() => setActiveTab(3)}
            className={`flex-1 py-3 px-4 font-medium transition-colors ${activeTab === 3 ? 'bg-white border-b-2 border-purple-500 text-purple-700' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            {t.tabBrain}
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">

          {/* TAB 1: DEFINITIONS */}
          {activeTab === 1 && (
            <div className="space-y-6 max-w-2xl mx-auto">
              <div>
                <label className="block font-bold text-gray-700 mb-2">{t.nodeDefLabel}</label>
                <input 
                  type="text" 
                  className="w-full border rounded p-3 focus:outline-purple-500 bg-gray-50"
                  placeholder={t.nodeDefPlace}
                  value={defs.nodeDefinition}
                  onChange={e => setDefs({...defs, nodeDefinition: e.target.value})}
                />
              </div>
              <div>
                <label className="block font-bold text-gray-700 mb-2">{t.edgeDefLabel}</label>
                <input 
                  type="text" 
                  className="w-full border rounded p-3 focus:outline-purple-500 bg-gray-50"
                  placeholder={t.edgeDefPlace}
                  value={defs.edgeDefinition}
                  onChange={e => setDefs({...defs, edgeDefinition: e.target.value})}
                />
              </div>
              <div>
                <label className="block font-bold text-gray-700 mb-2">{t.goalsLabel}</label>
                <textarea 
                  className="w-full border rounded p-3 focus:outline-purple-500 bg-gray-50 h-32"
                  placeholder={t.goalsPlace}
                  value={defs.projectGoals}
                  onChange={e => setDefs({...defs, projectGoals: e.target.value})}
                />
              </div>
              <div className="flex justify-end">
                <button 
                  onClick={() => setActiveTab(2)}
                  className="bg-purple-600 text-white px-6 py-2 rounded-lg hover:bg-purple-700 flex items-center gap-2"
                >
                  {translations[lang].architect.tabUpload} <ArrowRight size={16} />
                </button>
              </div>
            </div>
          )}

          {/* TAB 2: UPLOAD */}
          {activeTab === 2 && (
            <div className="flex flex-col items-center justify-center h-full space-y-6">
              <div 
                className="border-2 border-dashed border-gray-300 rounded-xl p-10 w-full max-w-xl flex flex-col items-center justify-center bg-gray-50 hover:bg-purple-50 transition-colors cursor-pointer"
                onClick={() => fileInputRef.current?.click()}
              >
                <FolderOpen size={48} className="text-purple-400 mb-4" />
                <h3 className="text-lg font-bold text-gray-700">{t.uploadLabel}</h3>
                <p className="text-sm text-gray-500 text-center mt-2">{t.uploadNote}</p>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  // @ts-ignore - webkitdirectory is non-standard but supported
                  webkitdirectory="" 
                  directory="" 
                  multiple 
                  onChange={handleFolderUpload}
                />
              </div>

              {uploadedFiles.length > 0 && (
                 <div className="w-full max-w-xl">
                   <div className="font-bold text-sm text-green-600 mb-2 flex items-center gap-2">
                     <Check size={16} /> {uploadedFiles.length} files prepared.
                   </div>
                   <button 
                    onClick={handleBuildGraph}
                    disabled={isProcessing}
                    className="w-full bg-purple-600 text-white py-3 rounded-lg font-bold hover:bg-purple-700 disabled:opacity-50 flex justify-center items-center gap-2"
                   >
                     {isProcessing ? <Loader2 className="animate-spin" /> : <Play size={20} />}
                     {isProcessing ? t.processing : t.uploadBtn}
                   </button>
                 </div>
              )}
            </div>
          )}

          {/* TAB 3: BRAINSTORM */}
          {activeTab === 3 && (
            <div className="flex flex-col h-full gap-4">
               <div className="bg-yellow-50 border border-yellow-200 p-3 rounded-lg text-xs text-yellow-800 flex items-center gap-2">
                 <FileText size={16} />
                 {t.shadowCopyNote}
               </div>

               <div className="flex gap-4">
                 <div className="flex-1 bg-gray-50 p-4 rounded-lg flex flex-col gap-3">
                   <h3 className="font-bold text-gray-700">{t.brainMode}</h3>
                   <textarea 
                     className="w-full border rounded p-2 text-sm h-24"
                     placeholder={t.feedbackPlace}
                     value={feedback}
                     onChange={e => setFeedback(e.target.value)}
                   />
                   <div className="flex gap-2">
                     <button 
                       onClick={handleGetSuggestions} 
                       disabled={isProcessing}
                       className="flex-1 bg-blue-600 text-white py-2 rounded hover:bg-blue-700 flex items-center justify-center gap-2 text-sm"
                     >
                        {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <BrainCircuit size={16} />}
                        {t.getSuggestions}
                     </button>
                     <button 
                        onClick={handleAutoComplete}
                        disabled={isProcessing}
                        className="flex-1 bg-purple-600 text-white py-2 rounded hover:bg-purple-700 flex items-center justify-center gap-2 text-sm"
                     >
                        {isProcessing ? <Loader2 className="animate-spin" size={16}/> : <Play size={16} />}
                        {t.autoComplete}
                     </button>
                   </div>
                 </div>
               </div>

               {/* Suggestions List */}
               <div className="flex-1 overflow-y-auto space-y-3">
                 {suggestions.map(s => (
                   <div key={s.id} className="border rounded-lg p-4 bg-white shadow-sm flex justify-between items-start gap-4 hover:shadow-md transition-shadow">
                      <div>
                        <div className="font-bold text-purple-700 flex items-center gap-2">
                          <span className="bg-purple-100 text-[10px] px-2 py-0.5 rounded uppercase">{s.type.replace('_', ' ')}</span>
                          {s.title}
                        </div>
                        <p className="text-sm text-gray-600 mt-1">{s.description}</p>
                      </div>
                      <div className="flex gap-2 shrink-0">
                        <button onClick={() => handleAcceptSuggestion(s)} className="text-green-600 hover:bg-green-50 p-1 rounded" title={t.apply}><Check size={20}/></button>
                        <button onClick={() => setSuggestions(prev => prev.filter(x => x.id !== s.id))} className="text-red-500 hover:bg-red-50 p-1 rounded" title={t.reject}><ThumbsDown size={20}/></button>
                      </div>
                   </div>
                 ))}
                 {suggestions.length === 0 && !isProcessing && (
                   <div className="text-center text-gray-400 mt-10 italic">
                     Ready for brainstorming...
                   </div>
                 )}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, Link as LinkIcon, Download, Upload, 
  Trash2, Save, MapPin, ChevronUp, ChevronDown, 
  Settings, Camera, FileJson, MousePointer2,
  Menu, HelpCircle, Eye, Check, X, Layers, FileText, Image as ImageIcon,
  Loader2, Globe, RefreshCw, Cake, Lightbulb, MessageSquare, Send, ArrowRightLeft,
  Undo2, Redo2, BrainCircuit
} from 'lucide-react';
import { AppState, GraphNodeData, GraphEdgeData, UIPanelsState, AttachedFile, Language, ChatMessage } from '../types';
import { translations, getDir } from '../utils/translations';
import { PresentationModal } from './PresentationModal';
import { AIArchitectModal } from './AIArchitectModal';

interface UIOverlayProps {
  appState: AppState;
  nodes: GraphNodeData[];
  edges: GraphEdgeData[];
  cameraPos: { x: number; y: number; z: number };
  uiPanels: UIPanelsState;
  setUiPanels: React.Dispatch<React.SetStateAction<UIPanelsState>>;
  setAppState: React.Dispatch<React.SetStateAction<AppState>>;
  onAddNode: () => void;
  onToggleEdgeMode: () => void;
  onUpdateItem: (id: string, type: 'node' | 'edge', data: Partial<GraphNodeData | GraphEdgeData>) => void;
  onDeleteItem: () => void;
  onExport: () => void;
  onImport: (file: File) => void;
  onCameraTeleport: (x: number, y: number, z: number) => void;
  hoverInfo: { label: string; summary: string; full: string } | null;
  onSelectSameColor: () => void;
  onFileUpload: (file: File) => void;
  onDeleteFile: (fileId: string) => void;
  presentationMode: { 
    isOpen: boolean; 
    content: string; 
    isLoading: boolean;
    activeFiles: AttachedFile[];
    targetLanguage: Language;
    activeItemId: string | null;
  };
  setPresentationMode: (mode: any) => void;
  onRegeneratePresentation: (lang: Language) => void;
  onCakePresentation: () => void;
  onSmartGuide: () => void;
  onAddFile: (file: AttachedFile, itemId: string) => void;
  onRemoveFile: (fileId: string, itemId: string) => void;
  onUndo: () => void;
  onRedo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onPushHistory: () => void;
  // AI Architect Props
  onApplyGraphFromAI: (nodes: any[], edges: any[]) => void;
  onApplyChangesFromAI: (changes: any) => void;
}

// Compact Panel (w-48)
const Panel: React.FC<{ title: string; icon: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean }> = ({ 
  title, icon, children, defaultOpen = true 
}) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  return (
    <div className="bg-white/95 backdrop-blur-sm border border-gray-200 rounded-lg shadow-lg overflow-hidden w-48 transition-all duration-200 pointer-events-auto shrink-0">
      <div 
        className="bg-gray-100 p-2 flex items-center justify-between cursor-pointer hover:bg-gray-200 select-none"
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="flex items-center gap-2 text-xs font-bold text-gray-700">
          {icon}
          <span>{title}</span>
        </div>
        {isOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
      </div>
      {isOpen && <div className="p-2 text-xs">{children}</div>}
    </div>
  );
};

const HelpModal: React.FC<{ onClose: () => void; lang: Language }> = ({ onClose, lang }) => {
  const t = translations[lang];
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" dir={getDir(lang)}>
      <div className="bg-white rounded-lg shadow-2xl max-w-lg w-full overflow-hidden">
        <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <HelpCircle size={20} /> {t.helpModal.title}
          </h2>
          <button onClick={onClose} className="hover:bg-slate-700 p-1 rounded"><X size={20}/></button>
        </div>
        <div className="p-6 space-y-4 text-gray-700 text-sm">
           <div className="space-y-2">
            <h3 className="font-bold border-b pb-1 text-slate-800">{t.helpModal.interaction}</h3>
            <ul className="list-disc list-inside space-y-1">
              <li><span className="font-semibold">{t.helpModal.interactionDesc1}</span></li>
              <li><span className="font-semibold">{t.helpModal.interactionDesc2}</span></li>
            </ul>
          </div>
          <div className="space-y-2">
            <h3 className="font-bold border-b pb-1 text-slate-800">{t.helpModal.manage}</h3>
            <ul className="list-disc list-inside space-y-1">
              <li><span className="font-semibold">{t.helpModal.manageDesc1}</span></li>
              <li><span className="font-semibold">{t.helpModal.manageDesc2}</span></li>
            </ul>
          </div>
        </div>
        <div className="bg-gray-100 p-4 flex justify-end">
          <button onClick={onClose} className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">{t.helpModal.btn}</button>
        </div>
