const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
const textModel = 'gemini-2.5-flash-image';
const reasoningModel = 'gemini-2.5-flash-image'; // Using a capable model for structure

// --- Helpers ---

const decodeFileContent = (base64Content: string) => {
  try {
    return atob(base64Content.split(',')[1]);
  } catch (e) {
    return "[Error decoding file]";
  }
};

const getFileParts = (files: any[]) => {
  const parts: any[] = [];
  let descriptions = "";
  let fullTextContext = "";

  if (files && files.length > 0) {
    files.forEach((file, index) => {
      if (file.type.startsWith('image/')) {
        const base64Data = file.content.split(',')[1];
        if (base64Data) {
          parts.push({
            inlineData: {
              mimeType: file.type,
              data: base64Data
            }
          });
          descriptions += `Image #${index + 1} ID: "${file.id}" (Filename: ${file.name})\n`;
        }
      } else if (file.type.startsWith('text/')) {
         const textContent = decodeFileContent(file.content);
         const textPart = `\n\n--- START OF FILE: ${file.name} ---\n${textContent}\n--- END OF FILE ---\n`;
         parts.push({ text: textPart });
         fullTextContext += textPart;
      }
    });
  }
  return { parts, descriptions, fullTextContext };
};

const getDeepGlobalContext = (nodes: GraphNodeData[], edges: GraphEdgeData[]) => {
  let context = "GLOBAL KNOWLEDGE GRAPH (RAG DATA):\n\n";

  nodes.forEach(n => {
    context += `NODE [${n.label}]:\n`;
    context += `Summary: ${n.summary}\n`;
    context += `Full Content: ${n.fullContent}\n`;

    if (n.files && n.files.length > 0) {
      context += "ATTACHED DOCUMENTS:\n";
      n.files.forEach(f => {
        if (f.type.startsWith('text/')) {
           context += `File: ${f.name}\nContent: ${decodeFileContent(f.content).substring(0, 2000)}...\n`; 
        }
      });
    }
    context += "--------------------------------------------------\n";
  });

  edges.forEach(e => {
     const from = nodes.find(n => n.id === e.fromId)?.label;
     const to = nodes.find(n => n.id === e.toId)?.label;
     let dirText = "Bidirectional connection";
     if (e.direction === 'source-to-target') dirText = `${from} --> ${to}`;
     else if (e.direction === 'target-to-source') dirText = `${to} --> ${from}`;

     context += `EDGE [${e.label}] from ${from} to ${to}\n`;
     context += `Direction: ${dirText}\n`;
     context += `Summary: ${e.summary}\n`;
     context += "--------------------------------------------------\n";
  });

  return context;
};

// --- Image Generation ---

export const generateImage = async (prompt: string): Promise<string | null> => {
  try {
    // Note: In a real scenario, use imagen-3.0-generate-001 or similar if available/authorized
    // Using flash-image for now if key allows, or failing gracefully
    const response = await ai.models.generateImages({
      model: 'imagen-3.0-generate-001', 
      prompt: prompt,
      config: {
        numberOfImages: 1,
        outputMimeType: 'image/jpeg',
        aspectRatio: '16:9',
      },
    });

    const base64EncodeString = response.generatedImages?.[0]?.image?.imageBytes;
    if (base64EncodeString) {
      return `data:image/jpeg;base64,${base64EncodeString}`;
    }
    return null;
  } catch (e) {
    console.error("Image gen error:", e);
    return null;
  }
};

// --- Multi-Mode Generation ---

export const generateModeContent = async (
  item: GraphNodeData | GraphEdgeData,
  mode: AIMode,
  targetLanguage: Language
): Promise<string> => {
  if (mode === 'presentation') {
    return generatePresentation(item, targetLanguage);
  }

  try {
    const langName = targetLanguage === 'fa' ? 'Persian (Farsi)' : 'English';
    const direction = targetLanguage === 'fa' ? 'rtl' : 'ltr';
    const { parts, descriptions } = getFileParts(item.files);

    let systemRole = "";
    let specificInstructions = "";

    switch (mode) {
      case 'writing':
        systemRole = "You are an expert Creative Writer and Editor.";
        specificInstructions = `
          Analyze this entity as a STORY ELEMENT (Character, Setting, or Plot Point).
          Structure your response as a Character/Location Sheet.
          Include:
          - Role in the story
          - Physical Description
          - Personality / Atmosphere
          - Backstory / History
          - Current Motivation
          - Secrets/Conflicts
          - Relationship to other elements (based on content)
        `;
        break;
      case 'coding':
        systemRole = "You are a Senior Software Architect and Documentation Lead.";
        specificInstructions = `
          Analyze this entity as a SOFTWARE COMPONENT (Module, Class, Service, or Function).
          Structure your response as Technical Documentation (Markdown style HTML).
          Include:
          - Component Overview & Purpose
          - Architecture Analysis
          - Key Responsibilities
          - Dependencies & Relationships
          - Usage Examples (Pseudo-code or pattern suggestions)
          - Potential Refactoring or Optimization ideas
        `;
        break;
      case 'law':
        systemRole = "You are a Senior Legal Consultant.";
        specificInstructions = `
          Analyze this entity as a LEGAL ENTITY (Contract clause, Person, Evidence, or Regulation).
          Structure your response as a Legal Brief or Memo.
          Include:
          - Definitions
          - Obligations/Rights
          - Legal Implications
          - Risk Analysis
          - References to statutes/precedents (if applicable in context)
          - Compliance Check
        `;
        break;
      case 'chemistry':
        systemRole = "You are a Chemistry and Science Expert.";
        specificInstructions = `
          Analyze this entity as a SCIENTIFIC ELEMENT (Molecule, Reaction, Lab Equipment, or Concept).
          Include:
          - Chemical/Physical Properties
          - Structure/Composition
          - Reactions/Interactions
          - Safety Data / Hazards
          - Applications & Usage
          - Mathematical Formulas (render as readable text/HTML)
        `;
        break;
    }

    const promptText = `
      ${systemRole}
      Output Language: ${langName}.

      Entity: ${item.label}
      Summary: ${item.summary}
      Full Content: ${item.fullContent}

      Available Images/Files:
      ${descriptions}

      TASK:
      ${specificInstructions}

      FORMATTING:
      - Clean HTML with inline CSS. Direction: ${direction}.
      - Use <img src="FILE_ID" class="ai-embedded-img" style="max-width:100%; border-radius:8px; margin: 10px 0;" /> for provided images.
      - Use <ai-image-gen prompt="Detailed prompt..."></ai-image-gen> if a visualization is needed but missing.
    `;

    parts.unshift({ text: promptText });

    const response = await ai.models.generateContent({
      model: textModel,
      contents: { parts: parts }
    });

    return response.text || "<h2>Error generating content</h2>";

  } catch (e) {
    return `<div style="color:red">Error: ${e instanceof Error ? e.message : 'Unknown'}</div>`;
  }
};

