             )}
          </div>

          <button onClick={onClose} className="p-2 hover:bg-slate-700 rounded-full transition-colors" title={t.close}>
            <X size={24} />
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden flex flex-col relative bg-gray-50">
        <div className="flex-1 overflow-y-auto p-4 md:p-8 flex justify-center bg-gray-100/50">
            <div className={`w-full max-w-5xl bg-white shadow-xl rounded-xl min-h-[600px] flex flex-col overflow-hidden transition-all ${isEditing ? 'max-w-[95%] ring-2 ring-blue-500' : ''}`}>

            {/* Header for Editor Mode */}
            {isEditing && (
                <div className="bg-blue-50 border-b border-blue-100 p-3 text-xs text-blue-800 flex items-center justify-between px-6">
                    <span className="font-bold flex items-center gap-2"><Edit size={14}/> WYSIWYG Editor Mode</span>
                    <span>Start typing directly below or drag images from the right sidebar.</span>
                </div>
            )}

            {isLoading ? (
                <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-4 py-20 flex-1">
                    <Loader2 size={48} className="animate-spin text-blue-500" />
                    <p className="text-lg animate-pulse">{t.loadingAI}</p>
                </div>
            ) : isEditing ? (
                <div className="flex-1 flex flex-row h-full overflow-hidden">
                    {/* Visual Editor Area */}
                    <div className="flex-1 p-8 overflow-y-auto">
                        <div 
                            ref={editorRef}
                            className="prose prose-lg max-w-none outline-none min-h-[500px] cursor-text [&_*]:box-border [&_*]:max-w-full"
                            contentEditable={true}
                            dir={targetLanguage === 'fa' ? 'rtl' : 'ltr'}
                            onDragOver={handleEditorDragOver}
                            onDrop={handleEditorDrop}
                        />
                    </div>

                    {/* Draggable Images Sidebar */}
                    <div className="w-72 bg-gray-50 border-l border-gray-200 p-4 flex flex-col gap-4 overflow-y-auto shrink-0 shadow-inner">
                        <h3 className="font-bold text-gray-700 text-sm flex items-center gap-2 border-b pb-2">
                           <ImagePlus size={16}/> Media Gallery
                        </h3>

                        {files.filter(f => f.type.startsWith('image/')).length === 0 ? (
                           <div className="text-xs text-gray-400 italic text-center py-8 bg-gray-100 rounded border border-dashed">
                               No images available.<br/>Generate AI images or upload files to see them here.
                           </div>
                        ) : (
                           <div className="space-y-3">
                               <div className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Drag & Drop</div>
                               {files.filter(f => f.type.startsWith('image/')).map(f => (
                                   <div key={f.id} className="group relative bg-white rounded-lg shadow-sm border hover:border-blue-500 transition-all p-2 cursor-grab active:cursor-grabbing" draggable onDragStart={(e) => handleDragStart(e, f)}>
                                      <div className="aspect-video bg-gray-100 rounded overflow-hidden mb-2 relative">
                                          <img 
                                            src={f.content} 
                                            alt={f.name}
                                            className="w-full h-full object-cover"
                                          />
                                          <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center">
                                              <GripVertical className="text-white opacity-0 group-hover:opacity-100 drop-shadow-md" />
                                          </div>
                                      </div>
                                      <div className="flex justify-between items-center">
                                         <div className="text-xs text-gray-600 truncate px-1 max-w-[150px]">{f.name}</div>
                                         {activeItemId && (
                                            <button 
                                              onClick={() => onRemoveFile(f.id, activeItemId)}
                                              className="text-red-400 hover:text-red-600 p-1 hover:bg-red-50 rounded"
                                              title="Delete Image"
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                         )}
                                      </div>
                                   </div>
                               ))}
                           </div>
                        )}
                    </div>
                </div>
            ) : (
                /* Viewer Area */
                <div className="p-8 md:p-12 overflow-y-auto">
                   <div 
                      className="prose prose-lg max-w-none [&_*]:box-border [&_*]:max-w-full [&_img]:max-w-full [&_img]:h-auto [&_pre]:max-w-full [&_pre]:overflow-x-auto" 
                      dir={targetLanguage === 'fa' ? 'rtl' : 'ltr'}
                   >
                    {(!localContent || localContent.trim() === "") ? (
                        <div className="flex flex-col items-center justify-center h-64 text-gray-400 border-2 border-dashed border-gray-200 rounded-xl">
                            <Edit size={48} className="mb-4 text-gray-300"/>
                            <p>{t.startWriting}</p>
                            <div className="flex gap-4 mt-4">
                                <button onClick={handleToggleEdit} className="text-blue-500 hover:underline font-bold">{t.edit}</button>
                                <span>or</span>
                                <button onClick={() => onRegenerate(targetLanguage)} className="text-purple-500 hover:underline font-bold">{t.generateAI}</button>
                            </div>
                        </div>
                    ) : (
                        renderContent()
                    )}
                   </div>
                </div>
            )}
            </div>
        </div>

        {/* Floating Chat Widget */}
        <ChatWidget 
          isOpen={isChatOpen} 
          onToggle={() => setIsChatOpen(!isChatOpen)}
          messages={messages}
          onSendMessage={handleSendMessage}
          isLoading={isChatLoading}
          lang={uiLang}
        />
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, Link as LinkIcon, Download, Upload, 
  Trash2, Save, MapPin, ChevronUp, ChevronDown, 
  Settings, Camera, FileJson, MousePointer2,
  Menu, HelpCircle, Eye, Check, X, Layers, FileText, Image as ImageIcon,
  Loader2, Globe, RefreshCw, Cake, Lightbulb, MessageSquare, Send, ArrowRightLeft,
  Undo2, Redo2, BrainCircuit, Bot, Sparkles, Box, Circle, Triangle, Cylinder, Disc
} from 'lucide-react';
import { AppState, GraphNodeData, GraphEdgeData, UIPanelsState, AttachedFile, Language, ChatMessage, AIMode, NodeShape } from '../types';
import { translations, getDir } from '../utils/translations';
import { PresentationModal } from './PresentationModal';
import { AIArchitectModal } from './AIArchitectModal';
import { FinalizationModal } from './FinalizationModal';

interface UIOverlayProps {
  appState: AppState;
  nodes: GraphNodeData[];
  edges: GraphEdgeData[];
  cameraPos: { x: number; y: number; z: number };
  uiPanels: UIPanelsState;
  setUiPanels: React.Dispatch<React.SetStateAction<UIPanelsState>>;
  setAppState: React.Dispatch<React.SetStateAction<AppState>>;
  onAddNode: () => void;
  onToggleEdgeMode: () => void;
  onUpdateItem: (id: string, type: 'node' | 'edge', data: Partial<GraphNodeData | GraphEdgeData>) => void;
  onDeleteItem: () => void;
  onExport: () => void;
  onImport: (file: File) => void;
  onCameraTeleport: (x: number, y: number, z: number) => void;
  hoverInfo: { label: string; summary: string; full: string } | null;
  onSelectSameColor: () => void;
  onFileUpload: (file: File) => void;
  onDeleteFile: (fileId: string) => void;
  presentationMode: { 
    isOpen: boolean; 
    content: string; 
    isLoading: boolean;
    activeFiles: AttachedFile[];
    targetLanguage: Language;
    activeItemId: string | null;
    modeTitle?: string;
  };
  setPresentationMode: (mode: any) => void;
  onRegeneratePresentation: (lang: Language) => void;
  onCakePresentation: () => void;
  onSmartGuide: () => void;
  onAddFile: (file: AttachedFile, itemId: string) => void;
  onRemoveFile: (fileId: string, itemId: string) => void;
  onUndo: () => void;
  onRedo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onPushHistory: () => void;
  // AI Architect Props
  onApplyGraphFromAI: (nodes: any[], edges: any[]) => void;
  onApplyChangesFromAI: (changes: any) => void;
}

// Compact Panel (w-48)
const Panel: React.FC<{ title: string; icon: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean }> = ({ 
  title, icon, children, defaultOpen = true 
}) => {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  return (
    <div className="bg-white/95 backdrop-blur-sm border border-gray-200 rounded-lg shadow-lg overflow-hidden w-48 transition-all duration-200 pointer-events-auto shrink-0">
      <div 
        className="bg-gray-100 p-2 flex items-center justify-between cursor-pointer hover:bg-gray-200 select-none"
        onClick={() => setIsOpen(!isOpen)}
      >
        <div className="flex items-center gap-2 text-xs font-bold text-gray-700">
          {icon}
          <span>{title}</span>
        </div>
        {isOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
      </div>
      {isOpen && <div className="p-2 text-xs">{children}</div>}
    </div>
  );
};

const HelpModal: React.FC<{ onClose: () => void; lang: Language }> = ({ onClose, lang }) => {
  const t = translations[lang];
  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" dir={getDir(lang)}>
      <div className="bg-white rounded-lg shadow-2xl max-w-lg w-full overflow-hidden">
        <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <HelpCircle size={20} /> {t.helpModal.title}
          </h2>
          <button onClick={onClose} className="hover:bg-slate-700 p-1 rounded"><X size={20}/></button>
        </div>
        <div className="p-6 space-y-4 text-gray-700 text-sm">
           <div className="space-y-2">
            <h3 className="font-bold border-b pb-1 text-slate-800">{t.helpModal.interaction}</h3>
            <ul className="list-disc list-inside space-y-1">
              <li><span className="font-semibold">{t.helpModal.interactionDesc1}</span></li>
              <li><span className="font-semibold">{t.helpModal.interactionDesc2}</span></li>
            </ul>
          </div>
          <div className="space-y-2">
            <h3 className="font-bold border-b pb-1 text-slate-800">{t.helpModal.manage}</h3>
            <ul className="list-disc list-inside space-y-1">
              <li><span className="font-semibold">{t.helpModal.manageDesc1}</span></li>
              <li><span className="font-semibold">{t.helpModal.manageDesc2}</span></li>
            </ul>
