export const UIOverlay: React.FC<UIOverlayProps> = ({
  appState, nodes, edges, cameraPos, uiPanels, setUiPanels, setAppState,
  onAddNode, onToggleEdgeMode, onUpdateItem, onDeleteItem,
  onExport, onImport, onCameraTeleport, hoverInfo, onSelectSameColor,
  onFileUpload, onDeleteFile, presentationMode, setPresentationMode,
  onRegeneratePresentation, onCakePresentation, onSmartGuide,
  onAddFile, onRemoveFile, onUndo, onRedo, canUndo, canRedo, onPushHistory,
  onApplyGraphFromAI, onApplyChangesFromAI
}) => {
  const [camInput, setCamInput] = useState({ x: 0, y: 10, z: 20 });
  const [activeMenu, setActiveMenu] = useState<'file' | 'view' | 'lang' | null>(null);
  const [showHelp, setShowHelp] = useState(false);
  const [showArchitect, setShowArchitect] = useState(false);
  const [showFinalize, setShowFinalize] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const attachmentInputRef = useRef<HTMLInputElement>(null);

  const lang = appState.appLanguage;
  const t = translations[lang];

  useEffect(() => {
    const handleClickOutside = () => setActiveMenu(null);
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  const togglePanel = (key: keyof UIPanelsState) => {
    setUiPanels(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const isMultiSelect = appState.selectedIds.length > 1;
  const activeNode = appState.activeType === 'node' ? nodes.find(n => n.id === appState.selectedIds[0]) : null;
  const activeEdge = appState.activeType === 'edge' ? edges.find(e => e.id === appState.selectedIds[0]) : null;
  const activeFiles = activeNode?.files || activeEdge?.files || [];

  return (
    <>
      {/* --- Top Navigation Bar --- */}
      <div 
        className="fixed top-0 left-0 right-0 h-12 bg-slate-800 text-white shadow-md z-[120] flex items-center px-4 justify-between select-none pointer-events-auto"
        onClick={(e) => e.stopPropagation()} 
        dir={getDir(lang)}
      >
        <div className="flex items-center gap-6 h-full">
          <div className="font-bold text-lg tracking-wider flex items-center gap-2">
            <span className="text-blue-400">Graph</span>Pro
          </div>

          <div className="flex items-center h-full gap-1">
             {/* Undo / Redo */}
             <div className="flex items-center gap-1 border-r border-slate-600 px-2 mx-2">
                <button 
                  onClick={onUndo} 
                  disabled={!canUndo} 
                  className="p-1.5 rounded hover:bg-slate-700 disabled:opacity-30 disabled:hover:bg-transparent"
                  title={t.undo}
                >
                  <Undo2 size={16} />
                </button>
                <button 
                  onClick={onRedo} 
                  disabled={!canRedo} 
                  className="p-1.5 rounded hover:bg-slate-700 disabled:opacity-30 disabled:hover:bg-transparent"
                  title={t.redo}
                >
                  <Redo2 size={16} />
                </button>
             </div>

             {/* Mode Selector */}
             <div className="flex items-center gap-2 mx-2 bg-slate-700 rounded px-2 py-1">
               <Bot size={16} className="text-green-400"/>
               <select 
                 className="bg-transparent text-xs text-white outline-none cursor-pointer w-24 md:w-auto"
                 value={appState.aiMode}
                 onChange={(e) => setAppState(prev => ({ ...prev, aiMode: e.target.value as AIMode }))}
               >
                 <option value="presentation" className="text-slate-900">{t.modes.presentation}</option>
                 <option value="writing" className="text-slate-900">{t.modes.writing}</option>
                 <option value="coding" className="text-slate-900">{t.modes.coding}</option>
                 <option value="law" className="text-slate-900">{t.modes.law}</option>
                 <option value="chemistry" className="text-slate-900">{t.modes.chemistry}</option>
                 <option value="investigation" className="text-slate-900">{t.modes.investigation}</option>
                 <option value="journalism" className="text-slate-900">{t.modes.journalism}</option>
                 <option value="gameDesign" className="text-slate-900">{t.modes.gameDesign}</option>
               </select>
             </div>

             {/* Dynamic AI Buttons (Visible when item selected) */}
             {(activeNode || activeEdge) && !presentationMode.isOpen && (
               <div className="flex items-center gap-1 mx-2 border-r border-slate-600 px-2 animate-in fade-in zoom-in duration-300">
                  <button 
                    onClick={onCakePresentation}
                    className="px-2 py-1 rounded bg-pink-600 hover:bg-pink-700 flex items-center gap-1 transition-colors shadow-sm font-medium text-xs whitespace-nowrap"
                    title={t.cakePres}
                  >
                    <Cake size={14} /> 
                    <span className="hidden xl:inline">{t.cakePres}</span>
                  </button>
                  <button 
                    onClick={onSmartGuide}
                    className="px-2 py-1 rounded bg-amber-600 hover:bg-amber-700 flex items-center gap-1 transition-colors shadow-sm font-medium text-xs whitespace-nowrap"
                    title={t.smartGuide}
                  >
                    <Lightbulb size={14} /> 
                    <span className="hidden xl:inline">{t.smartGuide}</span>
                  </button>
               </div>
             )}

             <div className="relative h-full flex items-center">
              <button onClick={(e) => { e.stopPropagation(); setActiveMenu(activeMenu === 'file' ? null : 'file'); }} className="px-3 py-1 rounded hover:bg-slate-700 transition-colors">{t.file}</button>
              {activeMenu === 'file' && <div className={`absolute top-10 ${lang === 'fa' ? 'right-0' : 'left-0'} w-48 bg-white text-slate-800 rounded shadow-xl z-50`}>
                   <button className="flex items-center gap-2 px-4 py-3 hover:bg-blue-50 w-full" onClick={onExport}><Save size={16}/> {t.save}</button>
                   <button className="flex items-center gap-2 px-4 py-3 hover:bg-blue-50 w-full" onClick={() => fileInputRef.current?.click()}><Upload size={16}/> {t.load}</button>
                   <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={(e) => { if (e.target.files?.[0]) onImport(e.target.files[0]); setActiveMenu(null); }} />
              </div>}
            </div>
             <div className="relative h-full flex items-center">
              <button onClick={(e) => { e.stopPropagation(); setActiveMenu(activeMenu === 'view' ? null : 'view'); }} className="px-3 py-1 rounded hover:bg-slate-700 transition-colors">{t.view}</button>
              {activeMenu === 'view' && <div className={`absolute top-10 ${lang === 'fa' ? 'right-0' : 'left-0'} w-56 bg-white text-slate-800 rounded shadow-xl z-50 p-2`}>
                   <label className="flex items-center gap-2 px-2 py-2 hover:bg-gray-50 rounded cursor-pointer"><input type="checkbox" checked={uiPanels.tools} onChange={() => togglePanel('tools')} className="rounded text-blue-600"/><span>{t.toolsPanel}</span></label>
                   <label className="flex items-center gap-2 px-2 py-2 hover:bg-gray-50 rounded cursor-pointer"><input type="checkbox" checked={uiPanels.properties} onChange={() => togglePanel('properties')} className="rounded text-blue-600"/><span>{t.propsPanel}</span></label>
                   <label className="flex items-center gap-2 px-2 py-2 hover:bg-gray-50 rounded cursor-pointer"><input type="checkbox" checked={uiPanels.camera} onChange={() => togglePanel('camera')} className="rounded text-blue-600"/><span>{t.camPanel}</span></label>
                   <label className="flex items-center gap-2 px-2 py-2 hover:bg-gray-50 rounded cursor-pointer"><input type="checkbox" checked={uiPanels.hints} onChange={() => togglePanel('hints')} className="rounded text-blue-600"/><span>{t.hintsPanel}</span></label>
              </div>}
            </div>
             <div className="relative h-full flex items-center">
              <button onClick={(e) => { e.stopPropagation(); setActiveMenu(activeMenu === 'lang' ? null : 'lang'); }} className="px-3 py-1 rounded hover:bg-slate-700 flex gap-1"><Globe size={16}/> {lang.toUpperCase()}</button>
              {activeMenu === 'lang' && <div className={`absolute top-10 ${lang === 'fa' ? 'right-0' : 'left-0'} w-32 bg-white text-slate-800 rounded shadow-xl z-50`}>
                   <button className="flex items-center gap-2 px-4 py-2 hover:bg-blue-50 w-full" onClick={() => setAppState(prev => ({ ...prev, appLanguage: 'fa' }))}>{t.persian}</button>
                   <button className="flex items-center gap-2 px-4 py-2 hover:bg-blue-50 w-full" onClick={() => setAppState(prev => ({ ...prev, appLanguage: 'en' }))}>{t.english}</button>
              </div>}
            </div>

             {/* AI Architect Button */}
             <button 
                onClick={() => setShowArchitect(true)}
                className="px-3 py-1 rounded bg-purple-600 hover:bg-purple-700 flex items-center gap-2 transition-colors mx-2 shadow-sm font-medium"
             >
                <BrainCircuit size={16} /> 
                <span className="hidden md:inline">{t.aiArchitect}</span>
             </button>

             {/* Finalize Button */}
             <button 
                onClick={() => setShowFinalize(true)}
                className="px-3 py-1 rounded bg-emerald-600 hover:bg-emerald-700 flex items-center gap-2 transition-colors shadow-sm font-medium ml-1"
             >
                <Sparkles size={16} /> 
                <span className="hidden md:inline">{t.finalize}</span>
             </button>

             <button onClick={() => setShowHelp(true)} className="px-3 py-1 rounded hover:bg-slate-700">{t.help}</button>
          </div>
        </div>
      </div>

      {showHelp && <HelpModal onClose={() => setShowHelp(false)} lang={lang} />}

      <AIArchitectModal 
        isOpen={showArchitect} 
        onClose={() => setShowArchitect(false)}
        lang={lang}
        nodes={nodes}
        edges={edges}
        onApplyGraph={onApplyGraphFromAI}
        onApplyChanges={onApplyChangesFromAI}
      />

      <FinalizationModal
        isOpen={showFinalize}
        onClose={() => setShowFinalize(false)}
        lang={lang}
        aiMode={appState.aiMode}
        nodes={nodes}
        edges={edges}
      />

      <PresentationModal 
        isOpen={presentationMode.isOpen} 
        isLoading={presentationMode.isLoading}
        content={presentationMode.content}
        files={presentationMode.activeFiles}
        targetLanguage={presentationMode.targetLanguage}
        activeItemId={presentationMode.activeItemId}
        modeTitle={presentationMode.modeTitle}
        nodes={nodes}
        edges={edges}
        uiLang={lang}
        onClose={() => setPresentationMode({ ...presentationMode, isOpen: false })}
        onRegenerate={onRegeneratePresentation}
        onSaveContent={(c) => {}} // Placeholder
        onAddFile={onAddFile}
        onRemoveFile={onRemoveFile}
      />

      {/* Sidebar Container: Tools & Camera */}
      <div className={`absolute top-16 ${lang === 'fa' ? 'right-4' : 'left-4'} z-10 flex flex-col gap-4 pointer-events-none`}>
        {uiPanels.tools && (
          <Panel title={t.toolTitle} icon={<Settings size={16} />}>
            <div className="flex flex-col gap-2">
              <button onClick={onAddNode} className="flex items-center gap-2 bg-blue-500 text-white p-2 rounded justify-center"><Plus size={16}/>{t.newNode}</button>
              <button onClick={onToggleEdgeMode} className="flex items-center gap-2 bg-gray-500 text-white p-2 rounded justify-center"><LinkIcon size={16}/>{appState.mode === 'select' ? t.connect : t.cancelConnect}</button>
              {appState.mode !== 'select' && (
                <div className="text-xs text-center text-orange-600 font-bold bg-orange-100 p-1 rounded border border-orange-200">
                  {appState.mode === 'edge-start' ? t.selectSource : t.selectTarget}
                </div>
              )}
            </div>
          </Panel>
        )}

        {uiPanels.camera && (
          <Panel title={t.camTitle} icon={<Camera size={16} />}>
             <div className="flex gap-1 mb-2">
                <input type="number" placeholder="X" className="w-1/3 border rounded p-1 text-xs text-center" value={camInput.x} onChange={e => setCamInput({...camInput, x: parseFloat(e.target.value)})} />
                <input type="number" placeholder="Y" className="w-1/3 border rounded p-1 text-xs text-center" value={camInput.y} onChange={e => setCamInput({...camInput, y: parseFloat(e.target.value)})} />
                <input type="number" placeholder="Z" className="w-1/3 border rounded p-1 text-xs text-center" value={camInput.z} onChange={e => setCamInput({...camInput, z: parseFloat(e.target.value)})} />
             </div>
             <button 
              onClick={() => onCameraTeleport(camInput.x, camInput.y, camInput.z)}
              className="w-full bg-slate-600 hover:bg-slate-700 text-white p-1.5 rounded text-xs flex items-center justify-center gap-1 transition-colors"
            >
               <MapPin size={12} /> {t.jump}
             </button>
             <div className="mt-2 text-center text-xs text-gray-500 font-mono">
               Pos: {Math.round(cameraPos.x)}, {Math.round(cameraPos.y)}, {Math.round(cameraPos.z)}
             </div>
          </Panel>
        )}
      </div>

      {/* Sidebar: Properties */}
      {uiPanels.properties && (
        <div className={`absolute top-16 ${lang === 'fa' ? 'left-4' : 'right-4'} z-10 flex flex-col max-h-[90vh] overflow-y-auto pl-1 gap-0 pointer-events-none`}>
          <Panel title={t.propTitle} icon={<MousePointer2 size={16} />}>
            {(activeNode || activeEdge) && (
              <div className="flex flex-col gap-3">

                 {isMultiSelect && (
                   <div className="bg-blue-50 border-b border-blue-100 p-2 mb-2 rounded text-blue-800 text-xs font-bold flex items-center gap-2">
                      <Layers size={14} />
                      <span>{appState.selectedIds.length} {t.multiSelect}</span>
                   </div>
                 )}

                 {!isMultiSelect && (
                   <button onClick={onSelectSameColor} className="flex items-center justify-center gap-2 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border border-indigo-200 p-1.5 rounded text-xs transition-colors mb-1">
                     <Eye size={14} /> <span>{t.selectSimilar}</span>
                   </button>
                 )}

                 <div>
                  <label className="text-xs text-gray-500 block mb-1">{t.label}</label>
                  <input 
                    type="text" 
                    className="w-full border rounded p-1 text-sm bg-gray-50 focus:bg-white transition-colors" 
                    value={activeNode?.label || activeEdge?.label} 
                    onFocus={onPushHistory} 
                    onChange={(e) => onUpdateItem(activeNode?.id || activeEdge!.id, activeNode ? 'node' : 'edge', { label: e.target.value })} 
                  />
                 </div>

                 {activeEdge && (
                    <div className="bg-orange-50 p-2 rounded border border-orange-100">
                      <label className="text-xs text-orange-800 block mb-1 font-bold flex items-center gap-1"><ArrowRightLeft size={10}/> Flow Direction</label>
                      <select 
                        className="w-full text-xs p-1 rounded border border-orange-200 bg-white"
                        value={activeEdge.direction || 'bidirectional'}
                        onFocus={onPushHistory}
                        onChange={(e) => onUpdateItem(activeEdge.id, 'edge', { direction: e.target.value as any })}
                      >
                         <option value="bidirectional">Bidirectional (Mutual)</option>
                         <option value="source-to-target">Source &rarr; Target</option>
                         <option value="target-to-source">Target &rarr; Source</option>
                      </select>
                    </div>
                 )}

                 {activeNode && (
                    <div>
                      <label className="text-xs text-gray-500 block mb-1">{t.shape}</label>
                      <div className="grid grid-cols-3 gap-1">
                        {['sphere', 'box', 'cylinder', 'capsule', 'torus', 'cone'].map((shape) => (
                           <button
                             key={shape}
                             onClick={() => { onPushHistory(); onUpdateItem(activeNode.id, 'node', { shape: shape as NodeShape }) }}
                             className={`p-1 rounded border flex flex-col items-center justify-center gap-1 text-[10px] ${activeNode.shape === shape || (!activeNode.shape && shape === 'sphere') ? 'bg-blue-100 border-blue-400 text-blue-700' : 'bg-white border-gray-200 hover:bg-gray-50'}`}
                             title={t.shapes[shape as keyof typeof t.shapes]}
                           >
                             {shape === 'sphere' && <Circle size={12} />}
                             {shape === 'box' && <Box size={12} />}
                             {shape === 'cylinder' && <Cylinder size={12} />}
                             {shape === 'capsule' && <div className="w-2 h-3 border rounded-full border-current" />}
                             {shape === 'torus' && <Disc size={12} />}
                             {shape === 'cone' && <Triangle size={12} />}
                             <span className="truncate w-full text-center">{t.shapes[shape as keyof typeof t.shapes]}</span>
                           </button>
                        ))}
                      </div>
                    </div>
                 )}

                 <div>
                  <label className="text-xs text-gray-500 block mb-1">{t.size}</label>
                  <input 
                    type="range" min={activeNode ? "0.5" : "0.05"} max={activeNode ? "3" : "0.5"} step="0.01" className="w-full" 
                    value={activeNode?.size || activeEdge?.size || 0.1} 
                    onPointerDown={onPushHistory}
                    onChange={(e) => onUpdateItem(activeNode?.id || activeEdge!.id, activeNode ? 'node' : 'edge', { size: parseFloat(e.target.value) })} 
                  />
                 </div>

                 <div>
                  <label className="text-xs text-gray-500 block mb-1">{t.color}</label>
                  <div className="flex gap-2">
                    <input 
                      type="color" className="w-8 h-8 cursor-pointer rounded border border-gray-300 p-0 overflow-hidden" 
                      value={activeNode?.color || activeEdge?.color} 
                      onClick={onPushHistory} 
                      onChange={(e) => onUpdateItem(activeNode?.id || activeEdge!.id, activeNode ? 'node' : 'edge', { color: e.target.value })} 
                    />
                    <div className="text-xs text-gray-400 flex items-center">{activeNode?.color || activeEdge?.color}</div>
                  </div>
                 </div>

                 <hr className="border-gray-200" />

                 <div className="bg-slate-50 p-2 rounded border border-slate-200">
                  <div className="flex justify-between items-center mb-2">
                     <span className="text-xs font-bold text-slate-600">{t.files}</span>
                     <button onClick={() => attachmentInputRef.current?.click()} className="text-xs bg-slate-200 p-1 rounded"><Plus size={14} /></button>
                     <input type="file" ref={attachmentInputRef} className="hidden" onChange={(e) => { if(e.target.files?.[0]) onFileUpload(e.target.files[0]); }} />
                  </div>
                  {activeFiles.length === 0 ? <div className="text-xs text-gray-400 text-center py-2">{t.noFiles}</div> : 
                    <div className="flex flex-col gap-1 max-h-40 overflow-y-auto pr-1">
                      {activeFiles.map(file => (
                        <div key={file.id} className="flex justify-between items-center bg-white border p-1 rounded text-xs">
                           <div className="flex items-center gap-1 overflow-hidden">
                             {file.type.startsWith('image') ? <ImageIcon size={10} className="text-blue-500"/> : <FileText size={10} className="text-gray-500"/>}
                             {file.isAiGenerated && <span className="text-[9px] bg-purple-100 text-purple-700 px-1 rounded">AI</span>}
                             <span className="truncate max-w-[120px]">{file.name}</span>
                           </div>
                           <button onClick={() => onDeleteFile(file.id)} className="text-red-500 hover:bg-red-50 p-0.5 rounded"><X size={12}/></button>
                        </div>
                      ))}
                    </div>
                  }
                </div>

                <hr className="border-gray-200" />

                <div>
                  <label className="text-xs text-gray-500 block mb-1">{t.summary}</label>
                  <textarea 
                    className="w-full border rounded p-1 text-sm h-16 bg-gray-50 focus:bg-white transition-colors" 
                    value={activeNode?.summary || activeEdge?.summary || ""} 
                    onFocus={onPushHistory}
                    onChange={(e) => onUpdateItem(activeNode?.id || activeEdge!.id, activeNode ? 'node' : 'edge', { summary: e.target.value })} 
                  />
                </div>

                <div>
                  <label className="text-xs text-gray-500 block mb-1">{t.fullContent}</label>
                  <textarea 
                    className="w-full border rounded p-1 text-sm h-24 bg-gray-50 focus:bg-white transition-colors" 
                    value={activeNode?.fullContent || activeEdge?.fullContent || ""} 
                    onFocus={onPushHistory}
                    onChange={(e) => onUpdateItem(activeNode?.id || activeEdge!.id, activeNode ? 'node' : 'edge', { fullContent: e.target.value })} 
                  />
                </div>

                <button onClick={onDeleteItem} className="mt-2 bg-red-100 hover:bg-red-200 text-red-600 p-2 rounded flex items-center justify-center gap-2 text-sm font-medium transition-colors">
                  <Trash2 size={16} /> <span>{t.delete}</span>
                </button>
              </div>
            )}

            {!activeNode && !activeEdge && (
              <div className="text-center text-gray-400 py-4 text-xs italic">
                {t.selectSource}
              </div>
            )}
          </Panel>
        </div>
      )}

      {/* Tooltip & Hints */}
      {hoverInfo && !presentationMode.isOpen && (
        <div 
          className="fixed z-30 pointer-events-none bg-gray-900/95 backdrop-blur text-white p-4 rounded-lg shadow-2xl border border-gray-600 max-w-sm transition-opacity left-1/2 -translate-x-1/2"
          style={{ bottom: '2rem' }} 
          dir={getDir(lang)}
        >
          <div className="font-bold text-xl mb-2 text-blue-300">{hoverInfo.label}</div>
          <div className="text-gray-300 text-sm mb-3 border-b border-gray-700 pb-2 leading-relaxed">{hoverInfo.summary}</div>
          <div className="text-gray-400 text-xs whitespace-pre-wrap leading-relaxed max-h-40 overflow-y-auto">{hoverInfo.full}</div>
        </div>
      )}

      {uiPanels.hints && (
        <div className="absolute bottom-4 right-4 text-xs text-gray-500 pointer-events-none bg-white/80 backdrop-blur-sm p-2 rounded border border-gray-200 shadow-sm z-10">
          {t.hints}
        </div>
      )}

    </>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Layers, Loader2, X, RefreshCw, Save, Edit, Bot, ImagePlus, Check, Trash2, GripVertical, Undo2, Redo2 } from 'lucide-react';
import { AttachedFile, Language, ChatMessage, GraphNodeData, GraphEdgeData } from '../types';
import { translations, getDir } from '../utils/translations';
import { ChatWidget } from './ChatWidget';
import { chatWithAI, generateImage } from '../services/ai';

interface PresentationModalProps {
  isOpen: boolean;
  isLoading: boolean;
  content: string;
  files: AttachedFile[];
  targetLanguage: Language;
  activeItemId: string | null;
  modeTitle?: string;
  nodes: GraphNodeData[];
  edges: GraphEdgeData[];
  onClose: () => void;
  onRegenerate: (lang: Language) => void;
  onSaveContent: (newContent: string) => void;
  uiLang: Language;
  onAddFile: (file: AttachedFile, itemId: string) => void;
  onRemoveFile: (fileId: string, itemId: string) => void;
}

// Component to handle individual AI generated images
const AIImagePlaceholder: React.FC<{ 
  prompt: string; 
  onConfirm: (base64: string) => void;
}> = ({ prompt, onConfirm }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const generate = async () => {
    setLoading(true);
    const result = await generateImage(prompt);
    if (result) {
      setImage(result);
    }
    setLoading(false);
  };

  return (
    <div className="my-6 border-2 border-dashed border-gray-300 rounded-xl overflow-hidden bg-gray-50 p-4 relative group transition-all hover:border-blue-400 shadow-sm">
      {loading ? (
        <div className="flex flex-col items-center justify-center h-64 text-gray-500 gap-3">
          <Loader2 className="animate-spin text-blue-600 w-10 h-10" />
          <span className="text-sm font-bold animate-pulse">Creating Visuals...</span>
        </div>
      ) : image ? (
        <div className="relative flex flex-col gap-3">
          <img src={image} alt="AI Generated" className="w-full h-auto object-cover max-h-[400px] rounded-lg shadow-md" />

          {/* Action Bar - Prominent Buttons */}
          <div className="flex items-center justify-center gap-4 mt-2 bg-white p-2 rounded-lg border shadow-sm">
             <button 
              onClick={() => onConfirm(image)}
              className="bg-green-600 hover:bg-green-700 text-white py-2 px-6 rounded-lg shadow transition-transform hover:scale-105 flex items-center gap-2"
              title="Save & Insert to Document"
            >
              <Check size={20} />
              <span className="font-bold">Insert Image</span>
            </button>
            <div className="w-px h-8 bg-gray-300 mx-2"></div>
            <button 
              onClick={generate}
              className="text-gray-700 hover:text-blue-600 hover:bg-blue-50 px-4 py-2 rounded-lg flex items-center gap-2 transition-colors"
              title="Try Again"
            >
              <RefreshCw size={18} />
              <span>Retry</span>
            </button>
            <button 
              onClick={() => setImage(null)}
              className="text-gray-700 hover:text-red-600 hover:bg-red-50 px-4 py-2 rounded-lg flex items-center gap-2 transition-colors"
              title="Discard"
            >
              <Trash2 size={18} />
              <span>Delete</span>
            </button>
          </div>
        </div>
      ) : (
        <div className="h-40 flex flex-col items-center justify-center gap-4 text-gray-500">
           <div className="text-sm italic bg-white px-4 py-2 rounded border shadow-sm max-w-[90%] text-center">Prompt: {prompt}</div>
           <button 
             onClick={generate}
             className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-8 py-2.5 rounded-full font-bold text-sm transition-colors shadow-md hover:shadow-lg"
           >
             <ImagePlus size={20} />
             Generate AI Image
           </button>
        </div>
      )}
    </div>
  );
};

export const PresentationModal: React.FC<PresentationModalProps> = ({ 
  isOpen, isLoading, content, files, targetLanguage, activeItemId, modeTitle, nodes, edges, onClose, onRegenerate, onSaveContent, uiLang, onAddFile, onRemoveFile 
}) => {
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  // Edit Mode State
  const [isEditing, setIsEditing] = useState(false);
  const [localContent, setLocalContent] = useState(content);

  // Ref for the WYSIWYG editor
  const editorRef = useRef<HTMLDivElement>(null);

  const t = translations[uiLang];

  // Sync content when prop changes
  useEffect(() => {
    setLocalContent(content);
    if (editorRef.current) {
        editorRef.current.innerHTML = content;
    }
  }, [content, isOpen]); // Sync on open as well

  if (!isOpen) return null;

  const handleConfirmImage = (originalTag: string, base64: string) => {
    if (!activeItemId) return;

    // 1. Create File
    const newFile = {
        id: crypto.randomUUID(),
        name: `AI_GEN_${Date.now()}.jpg`,
        type: 'image/jpeg',
        content: base64,
        isAiGenerated: true
    };
    onAddFile(newFile, activeItemId);

    // 2. Replace Tag in Content permanently
    const imgTag = `<img src="${newFile.id}" class="ai-embedded-img" style="max-width:100%; height:auto; border-radius:8px; margin: 10px 0; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); display: block;" />`;
    const newContent = localContent.replace(originalTag, imgTag);

    setLocalContent(newContent);
    onSaveContent(newContent); // Persist immediately

    // Update editor view if in edit mode
    if (editorRef.current) {
        editorRef.current.innerHTML = newContent;
    }
  };

  // --- Content Parsing Logic (For View Mode) ---
  const renderContent = () => {
    if (isLoading) return null;

    let processedHTML = localContent;

    // Pre-process images for display (replace ID with Base64)
    if (files.length > 0) {
      files.forEach(file => {
        if (file.type.startsWith('image/')) {
          const placeholder = `"${file.id}"`; 
          const replacement = `"${file.content}"`;
          processedHTML = processedHTML.replaceAll(placeholder, replacement);
        }
      });
    }

    // Split content by the custom tag
    const parts = processedHTML.split(/(<ai-image-gen prompt=".*?"><\/ai-image-gen>)/g);

    return parts.map((part, index) => {
      const match = part.match(/<ai-image-gen prompt="(.*?)"><\/ai-image-gen>/);
      if (match) {
        const prompt = match[1];
        return (
          <AIImagePlaceholder 
            key={index} 
            prompt={prompt} 
            onConfirm={(base64) => handleConfirmImage(part, base64)}
          />
        );
      }
      return <div key={index} dangerouslySetInnerHTML={{ __html: part }} className="inline" />;
    });
  };

  const handleSendMessage = async (text: string) => {
    const activeItem = nodes.find(n => n.id === activeItemId) || edges.find(e => e.id === activeItemId);
    if (!activeItem) return;

    const newMessage: ChatMessage = { id: crypto.randomUUID(), role: 'user', text, timestamp: Date.now() };
    setMessages(prev => [...prev, newMessage]);
    setIsChatLoading(true);

    const response = await chatWithAI(text, messages, activeItem, nodes, edges, uiLang);

    setIsChatLoading(false);
    setMessages(prev => [...prev, { id: crypto.randomUUID(), role: 'assistant', text: response, timestamp: Date.now() }]);
  };

  const handleSave = () => {
      if (editorRef.current) {
        const updatedHTML = editorRef.current.innerHTML;
        onSaveContent(updatedHTML);
        setLocalContent(updatedHTML);
      }
      setIsEditing(false);
  };

  const handleToggleEdit = () => {
      if (!isEditing) {
          let editableContent = localContent;
          files.forEach(file => {
            if (file.type.startsWith('image/')) {
               editableContent = editableContent.replaceAll(`"${file.id}"`, `"${file.content}"`);
            }
          });

          setTimeout(() => {
              if (editorRef.current) editorRef.current.innerHTML = editableContent;
          }, 0);
      } else {
          setLocalContent(content);
      }
      setIsEditing(!isEditing);
  };

  // --- Drag and Drop Handlers ---
  const handleDragStart = (e: React.DragEvent, file: AttachedFile) => {
      const imgTag = `<img src="${file.content}" data-file-id="${file.id}" class="ai-embedded-img" style="max-width:100%; height:auto; border-radius:8px; margin: 10px 0; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); display: block;" />`;
      e.dataTransfer.setData('text/html', imgTag);
      e.dataTransfer.effectAllowed = 'copy';
  };

  const handleEditorDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleEditorDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const html = e.dataTransfer.getData('text/html');

    if (html) {
       // Attempt to drop at cursor position
       let range = null;
       // @ts-ignore
       if (document.caretRangeFromPoint) { // Webkit
          // @ts-ignore
          range = document.caretRangeFromPoint(e.clientX, e.clientY);
       } else if ((document as any).caretPositionFromPoint) { // Firefox
          const pos = (document as any).caretPositionFromPoint(e.clientX, e.clientY);
          if (pos) {
             range = document.createRange();
             range.setStart(pos.offsetNode, pos.offset);
             range.collapse(true);
          }
       }

       if (range) {
          const selection = window.getSelection();
          if (selection) {
             selection.removeAllRanges();
             selection.addRange(range);
          }
       }

       document.execCommand('insertHTML', false, html);
    }
  };

  return (
    <div className="fixed inset-0 top-12 z-[100] bg-white flex flex-col animate-in fade-in duration-300 shadow-2xl" dir={getDir(uiLang)}>
      {/* Header */}
      <div className="h-16 bg-slate-900 text-white flex items-center justify-between px-6 shadow-md shrink-0">
        <div className="flex items-center gap-2">
          <Layers className="text-blue-400" />
          <h1 className="text-xl font-bold">{modeTitle || t.presentationTitle}</h1>
        </div>

        <div className="flex items-center gap-4">

          {/* Edit / Save Toolbar */}
          <div className="flex items-center gap-2 mr-4">
             {isEditing ? (
                 <>
                    {/* Text specific Undo/Redo for the editor */}
                    <div className="flex items-center gap-1 bg-slate-800 rounded p-1 mx-2 border border-slate-700">
                        <button onClick={() => document.execCommand('undo')} className="p-1.5 hover:bg-slate-700 rounded text-gray-300 hover:text-white" title={t.undo}>
                            <Undo2 size={18} />
                        </button>
                        <button onClick={() => document.execCommand('redo')} className="p-1.5 hover:bg-slate-700 rounded text-gray-300 hover:text-white" title={t.redo}>
                            <Redo2 size={18} />
                        </button>
                    </div>

                    <button onClick={handleSave} className="flex items-center gap-2 bg-green-600 hover:bg-green-700 px-4 py-2 rounded-lg text-sm font-bold transition-colors shadow-sm">
                        <Save size={18} /> {t.saveChanges}
                    </button>
                    <button onClick={handleToggleEdit} className="flex items-center gap-2 bg-gray-600 hover:bg-gray-700 px-4 py-2 rounded-lg text-sm transition-colors shadow-sm">
                        <X size={18} /> {t.discard}
                    </button>
                 </>
             ) : (
                 <>
                    <button onClick={handleToggleEdit} className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 px-4 py-2 rounded-lg text-sm font-bold transition-colors shadow-sm">
                        <Edit size={18} /> {t.edit}
                    </button>

                    <div className="h-6 w-px bg-slate-700 mx-2"></div>

                    <div className="flex items-center gap-1">
                        <select 
                        className="bg-slate-800 text-sm outline-none cursor-pointer text-white border border-slate-700 rounded px-2 py-2"
                        value={targetLanguage}
                        disabled={isLoading}
                        onChange={(e) => onRegenerate(e.target.value as Language)} 
                        >
                            <option value="fa">{t.persian}</option>
                            <option value="en">{t.english}</option>
                        </select>
                        <button 
                            onClick={() => onRegenerate(targetLanguage)}
                            disabled={isLoading}
                            className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700 px-4 py-2 rounded-lg text-sm font-bold transition-colors disabled:opacity-50 shadow-sm"
                        >
                            {isLoading ? <Loader2 size={18} className="animate-spin"/> : <Bot size={18} />} 
                            {t.generateAI}
                        </button>
                    </div>
                 </>
             )}
          </div>

          <button onClick={onClose} className="p-2 hover:bg-slate-700 rounded-full transition-colors" title={t.close}>
            <X size={24} />
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden flex flex-col relative bg-gray-50">
        <div className="flex-1 overflow-y-auto p-4 md:p-8 flex justify-center bg-gray-100/50">
            <div className={`w-full max-w-5xl bg-white shadow-xl rounded-xl min-h-[600px] flex flex-col overflow-hidden transition-all ${isEditing ? 'max-w-[95%] ring-2 ring-blue-500' : ''}`}>

            {/* Header for Editor Mode */}
            {isEditing && (
                <div className="bg-blue-50 border-b border-blue-100 p-3 text-xs text-blue-800 flex items-center justify-between px-6">
                    <span className="font-bold flex items-center gap-2"><Edit size={14}/> WYSIWYG Editor Mode</span>
                    <span>Start typing directly below or drag images from the right sidebar.</span>
                </div>
            )}

            {isLoading ? (
                <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-4 py-20 flex-1">
                    <Loader2 size={48} className="animate-spin text-blue-500" />
                    <p className="text-lg animate-pulse">{t.loadingAI}</p>
                </div>
            ) : isEditing ? (
                <div className="flex-1 flex flex-row h-full overflow-hidden">
                    {/* Visual Editor Area */}
                    <div className="flex-1 p-8 overflow-y-auto">
                        <div 
                            ref={editorRef}
                            className="prose prose-lg max-w-none outline-none min-h-[500px] cursor-text [&_*]:box-border [&_*]:max-w-full"
                            contentEditable={true}
                            dir={targetLanguage === 'fa' ? 'rtl' : 'ltr'}
                            onDragOver={handleEditorDragOver}
                            onDrop={handleEditorDrop}
                        />
                    </div>

                    {/* Draggable Images Sidebar */}
                    <div className="w-72 bg-gray-50 border-l border-gray-200 p-4 flex flex-col gap-4 overflow-y-auto shrink-0 shadow-inner">
                        <h3 className="font-bold text-gray-700 text-sm flex items-center gap-2 border-b pb-2">
                           <ImagePlus size={16}/> Media Gallery
                        </h3>

                        {files.filter(f => f.type.startsWith('image/')).length === 0 ? (
                           <div className="text-xs text-gray-400 italic text-center py-8 bg-gray-100 rounded border border-dashed">
                               No images available.<br/>Generate AI images or upload files to see them here.
                           </div>
                        ) : (
                           <div className="space-y-3">
                               <div className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Drag & Drop</div>
                               {files.filter(f => f.type.startsWith('image/')).map(f => (
                                   <div key={f.id} className="group relative bg-white rounded-lg shadow-sm border hover:border-blue-500 transition-all p-2 cursor-grab active:cursor-grabbing" draggable onDragStart={(e) => handleDragStart(e, f)}>
                                      <div className="aspect-video bg-gray-100 rounded overflow-hidden mb-2 relative">
                                          <img 
                                            src={f.content} 
                                            alt={f.name}
                                            className="w-full h-full object-cover"
                                          />
                                          <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center">
                                              <GripVertical className="text-white opacity-0 group-hover:opacity-100 drop-shadow-md" />
                                          </div>
                                      </div>
                                      <div className="flex justify-between items-center">
                                         <div className="text-xs text-gray-600 truncate px-1 max-w-[150px]">{f.name}</div>
                                         {activeItemId && (
                                            <button 
                                              onClick={() => onRemoveFile(f.id, activeItemId)}
                                              className="text-red-400 hover:text-red-600 p-1 hover:bg-red-50 rounded"
                                              title="Delete Image"
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                         )}
                                      </div>
                                   </div>
                               ))}
                           </div>
                        )}
                    </div>
                </div>
            ) : (
                /* Viewer Area */
                <div className="p-8 md:p-12 overflow-y-auto">
                   <div 
                      className="prose prose-lg max-w-none [&_*]:box-border [&_*]:max-w-full [&_img]:max-w-full [&_img]:h-auto [&_pre]:max-w-full [&_pre]:overflow-x-auto" 
                      dir={targetLanguage === 'fa' ? 'rtl' : 'ltr'}
                   >
                    {(!localContent || localContent.trim() === "") ? (
                        <div className="flex flex-col items-center justify-center h-64 text-gray-400 border-2 border-dashed border-gray-200 rounded-xl">
                            <Edit size={48} className="mb-4 text-gray-300"/>
                            <p>{t.startWriting}</p>
                            <div className="flex gap-4 mt-4">
                                <button onClick={handleToggleEdit} className="text-blue-500 hover:underline font-bold">{t.edit}</button>
                                <span>or</span>
                                <button onClick={() => onRegenerate(targetLanguage)} className="text-purple-500 hover:underline font-bold">{t.generateAI}</button>
                            </div>
                        </div>
                    ) : (
                        renderContent()
                    )}
                   </div>
                </div>
            )}
            </div>
        </div>

        {/* Floating Chat Widget */}
        <ChatWidget 
          isOpen={isChatOpen} 
          onToggle={() => setIsChatOpen(!isChatOpen)}
          messages={messages}
          onSendMessage={handleSendMessage}
          isLoading={isChatLoading}
          lang={uiLang}
        />
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, Suspense, useRef } from 'react';
import { Canvas, useThree, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid } from '@react-three/drei';
import * as THREE from 'three';
import { GraphNode } from './components/GraphNode';
import { GraphEdge } from './components/GraphEdge';
import { UIOverlay } from './components/UIOverlay';
import { GraphNodeData, GraphEdgeData, AppState, CameraState, UIPanelsState, AttachedFile, Language } from './types';
import { generatePresentation, generateCakePresentation, generateSmartGuide, generateModeContent } from './services/ai';
import { getDir, translations } from './utils/translations';

// Keyboard Control Component for Arrow navigation ONLY
const KeyboardControls = () => {
  const { camera, controls } = useThree();
  const [keys, setKeys] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => setKeys((k) => ({ ...k, [e.code]: true }));
    const handleKeyUp = (e: KeyboardEvent) => setKeys((k) => ({ ...k, [e.code]: false }));

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useFrame((state, delta) => {
    // @ts-ignore
    if (!controls || !controls.enabled) return;

    const speed = 20 * delta; 
    const moveVector = new THREE.Vector3();

    const forward = new THREE.Vector3();
    camera.getWorldDirection(forward);
    forward.y = 0;
    forward.normalize();

    const right = new THREE.Vector3();
    right.crossVectors(forward, new THREE.Vector3(0, 1, 0));
    right.normalize();

    // Removed WASD to prevent typing conflict
    if (keys['ArrowUp']) moveVector.add(forward.multiplyScalar(speed));
    if (keys['ArrowDown']) moveVector.add(forward.multiplyScalar(-speed));
    if (keys['ArrowRight']) moveVector.add(right.multiplyScalar(-speed));
    if (keys['ArrowLeft']) moveVector.add(right.multiplyScalar(speed));

    if (moveVector.lengthSq() > 0) {
      camera.position.add(moveVector);
      // @ts-ignore
      if (controls.target) {
         // @ts-ignore
         controls.target.add(moveVector);
      }
    }
  });

  return null;
};

const CameraReporter: React.FC<{ onUpdate: (pos: THREE.Vector3) => void }> = ({ onUpdate }) => {
  const { camera } = useThree();
  useThree(({ camera }) => {
    onUpdate(camera.position);
  });
  return null;
};

const CameraController: React.FC<{ targetPos: CameraState | null }> = ({ targetPos }) => {
  const { camera, controls } = useThree();
  useEffect(() => {
    if (targetPos) {
      camera.position.set(targetPos.x, targetPos.y, targetPos.z);
      // @ts-ignore
      controls?.target?.set(targetPos.x, 0, targetPos.z - 10);
      // @ts-ignore
      controls?.update();
    }
  }, [targetPos, camera, controls]);
  return null;
};

const App: React.FC = () => {
  const [nodes, setNodes] = useState<GraphNodeData[]>([]);
  const [edges, setEdges] = useState<GraphEdgeData[]>([]);
  const [appState, setAppState] = useState<AppState>({
    nodes: [],
    edges: [],
    selectedIds: [],
    activeType: null,
    mode: 'select',
    edgeStartNodeId: null,
    appLanguage: 'fa',
    aiMode: 'presentation'
  });

  // History Stacks for Undo/Redo
  const [history, setHistory] = useState<{nodes: GraphNodeData[], edges: GraphEdgeData[]}[]>([]);
  const [future, setFuture] = useState<{nodes: GraphNodeData[], edges: GraphEdgeData[]}[]>([]);

  const [cameraPosDisplay, setCameraPosDisplay] = useState({ x: 0, y: 10, z: 20 });
  const [targetCameraPos, setTargetCameraPos] = useState<CameraState | null>(null);
  const [hoverData, setHoverData] = useState<{ label: string; summary: string; full: string } | null>(null);

  const [uiPanels, setUiPanels] = useState<UIPanelsState>({
    tools: true,
    properties: true,
    camera: true,
    hints: true,
    filePanel: false 
  });

  const [presentationMode, setPresentationMode] = useState<{ 
    isOpen: boolean; 
    content: string; 
    isLoading: boolean;
    activeFiles: AttachedFile[]; 
    targetLanguage: Language;
    activeItemId: string | null;
    modeTitle?: string;
  }>({
    isOpen: false,
    content: '',
    isLoading: false,
    activeFiles: [],
    targetLanguage: 'fa',
    activeItemId: null
  });

  // --- History Management ---
  const saveHistory = useCallback(() => {
    setHistory(prev => {
      // Optimization: Optionally check if the new state is identical to the last to avoid dups
      // But for simplicity and correctness with "pre-action" saving, we just push.
      return [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }];
    });
    setFuture([]); // Clear redo stack on new action
  }, [nodes, edges]);

  const undo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    const newHistory = history.slice(0, -1);

    setFuture(prev => [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }]);
    setNodes(previous.nodes);
    setEdges(previous.edges);
    setHistory(newHistory);
  }, [history, nodes, edges]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[future.length - 1];
    const newFuture = future.slice(0, -1);

    setHistory(prev => [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }]);
    setNodes(next.nodes);
    setEdges(next.edges);
    setFuture(newFuture);
  }, [future, nodes, edges]);

  // Keyboard Shortcuts for Undo/Redo
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
        if (e.shiftKey) {
          redo();
        } else {
          undo();
        }
      } else if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  useEffect(() => {
    const saved = localStorage.getItem('graph_pro_data');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setNodes(parsed.nodes || []);
        setEdges(parsed.edges || []);
      } catch (e) {
        console.error("Failed to load save data", e);
      }
    } else {
      handleAddNode();
    }
  }, []);

  useEffect(() => {
    const data = { nodes, edges };
    localStorage.setItem('graph_pro_data', JSON.stringify(data));
  }, [nodes, edges]);

  useEffect(() => {
    document.documentElement.dir = getDir(appState.appLanguage);
    document.documentElement.lang = appState.appLanguage;
  }, [appState.appLanguage]);

  const handleAddNode = useCallback(() => {
    saveHistory(); // Snapshot
    const newNode: GraphNodeData = {
      id: crypto.randomUUID(),
      label: `Node ${nodes.length + 1}`,
      summary: "Short summary...",
      fullContent: "", // Initialize empty as per requirement
      color: "#2196F3",
      size: 1,
      position: [(Math.random() * 10) - 5, 0, (Math.random() * 10) - 5],
      files: []
    };
    setNodes(prev => [...prev, newNode]);
    setAppState(prev => ({ ...prev, selectedIds: [newNode.id], activeType: 'node', mode: 'select' }));
  }, [nodes, saveHistory]);

  const handleNodeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();
    setAppState(prev => {
      if (prev.mode === 'select') {
        return { ...prev, selectedIds: [id], activeType: 'node' };
      } 
      else if (prev.mode === 'edge-start') {
        return { ...prev, edgeStartNodeId: id, mode: 'edge-finish' };
      } 
      else if (prev.mode === 'edge-finish') {
        if (prev.edgeStartNodeId && prev.edgeStartNodeId !== id) {
           saveHistory(); // Snapshot before creating edge
           const newEdge: GraphEdgeData = {
             id: crypto.randomUUID(),
             fromId: prev.edgeStartNodeId,
             toId: id,
             label: 'Connection',
             color: '#666666',
             size: 0.1,
             summary: "Connection...",
             fullContent: "",
             files: [],
             direction: 'bidirectional'
           };
           setEdges(current => [...current, newEdge]);
           return { ...prev, mode: 'select', selectedIds: [], activeType: null, edgeStartNodeId: null };
        }
        return { ...prev, mode: 'select' };
      }
      return prev;
    });
  }, [saveHistory]);

  const handleEdgeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, selectedIds: [id], activeType: 'edge' }));
    }
  }, [appState.mode]);

  const handleBackgroundClick = useCallback(() => {
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, selectedIds: [], activeType: null }));
    }
  }, [appState.mode]);

  // --- Image Save Handler (for Generated Images) ---
  const handleAddFile = useCallback((file: AttachedFile, itemId: string) => {
    saveHistory();
    // Save generated image to node/edge state
    const targetNode = nodes.find(n => n.id === itemId);
    if (targetNode) {
        setNodes(prev => prev.map(n => n.id === itemId ? { ...n, files: [...n.files, file] } : n));
        return;
    }
    const targetEdge = edges.find(e => e.id === itemId);
    if (targetEdge) {
        setEdges(prev => prev.map(e => e.id === itemId ? { ...e, files: [...e.files, file] } : e));
    }
  }, [nodes, edges, saveHistory]);

  const handleRemoveFile = useCallback((fileId: string, itemId: string) => {
    saveHistory();
    const targetNode = nodes.find(n => n.id === itemId);
    if (targetNode) {
        setNodes(prev => prev.map(n => n.id === itemId ? { ...n, files: n.files.filter(f => f.id !== fileId) } : n));
        return;
    }
    const targetEdge = edges.find(e => e.id === itemId);
    if (targetEdge) {
        setEdges(prev => prev.map(e => e.id === itemId ? { ...e, files: e.files.filter(f => f.id !== fileId) } : e));
    }
  }, [nodes, edges, saveHistory]);

  // --- AI Presentation Handlers ---
  const openPresentation = (content: string, item: GraphNodeData | GraphEdgeData, title: string, isLoading = false) => {
     setPresentationMode({
        isOpen: true,
        content: content,
        isLoading: isLoading,
        activeFiles: item.files || [],
        targetLanguage: appState.appLanguage,
        activeItemId: item.id,
        modeTitle: title
      });
  };

  const handleDoubleClick = useCallback(async (e: any, id: string) => {
    e.stopPropagation();
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      // Determine title based on current mode
      const t = translations[appState.appLanguage];
      let modeTitle = t.presentationTitle;
      if (appState.aiMode !== 'presentation') {
        modeTitle = t.modes[appState.aiMode];
      }

      // NO AUTOMATIC GENERATION here. Just open with existing content.
      openPresentation(target.fullContent || "", target, modeTitle, false);
    }
  }, [nodes, edges, appState.appLanguage, appState.aiMode]);

  const handleCakePresentation = useCallback(async () => {
    const id = appState.selectedIds[0];
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      const t = translations[appState.appLanguage];
      openPresentation(target.fullContent || "", target, t.cakePres, true);
      const htmlContent = await generateCakePresentation(target, appState.appLanguage);
      handleSaveModalContent(htmlContent); // Save result
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  }, [nodes, edges, appState.selectedIds, appState.appLanguage]);

  const handleSmartGuide = useCallback(async () => {
    const id = appState.selectedIds[0];
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      const t = translations[appState.appLanguage];
      openPresentation(target.fullContent || "", target, t.smartGuide, true);
      const htmlContent = await generateSmartGuide(target, nodes, edges, appState.appLanguage);
      handleSaveModalContent(htmlContent); // Save result
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  }, [nodes, edges, appState.selectedIds, appState.appLanguage]);

  const handleSaveModalContent = useCallback((newContent: string) => {
     saveHistory();
     const id = presentationMode.activeItemId;
     if (!id) return;

     // Update Node/Edge State
     const targetNode = nodes.find(n => n.id === id);
     if (targetNode) {
        setNodes(prev => prev.map(n => n.id === id ? { ...n, fullContent: newContent } : n));
     } else {
        const targetEdge = edges.find(e => e.id === id);
        if (targetEdge) {
            setEdges(prev => prev.map(e => e.id === id ? { ...e, fullContent: newContent } : e));
        }
     }
  }, [nodes, edges, presentationMode.activeItemId, saveHistory]);

  const regeneratePresentation = async (lang: Language) => {
    const id = presentationMode.activeItemId;
    if (!id) return;
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      setPresentationMode(prev => ({ ...prev, isLoading: true, targetLanguage: lang }));
      const htmlContent = await generateModeContent(target, appState.aiMode, lang);
      handleSaveModalContent(htmlContent); // Save result
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  };

  const handleDragNode = useCallback((id: string, newPos: [number, number, number]) => {
    // Note: saveHistory is triggered by onDragStart in GraphNode component
    setNodes(prev => {
      const draggedNode = prev.find(n => n.id === id);
      if (!draggedNode) return prev;
      const dx = newPos[0] - draggedNode.position[0];
      const dy = newPos[1] - draggedNode.position[1];
      const dz = newPos[2] - draggedNode.position[2];

      if (appState.selectedIds.includes(id)) {
        return prev.map(n => {
          if (appState.selectedIds.includes(n.id)) {
             return { ...n, position: [n.position[0] + dx, n.position[1] + dy, n.position[2] + dz] };
          }
          return n;
        });
      }
      return prev.map(n => n.id === id ? { ...n, position: newPos } : n);
    });
  }, [appState.selectedIds]);

  const handleUpdateItem = useCallback((id: string, type: 'node' | 'edge', data: any) => {
    // Note: saveHistory is triggered by onPushHistory (onFocus/onClick) in UIOverlay
    const targetIds = appState.selectedIds.includes(id) ? appState.selectedIds : [id];
    if (type === 'node') {
      setNodes(prev => prev.map(n => targetIds.includes(n.id) ? { ...n, ...data } : n));
    } else {
      setEdges(prev => prev.map(e => targetIds.includes(e.id) ? { ...e, ...data } : e));
    }
  }, [appState.selectedIds]);

  const handleFileUpload = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      saveHistory();
      const result = e.target?.result as string; 
      const newFile: AttachedFile = {
        id: crypto.randomUUID(),
        name: file.name,
        type: file.type,
        content: result
      };
      const { selectedIds, activeType } = appState;
      if (activeType === 'node') {
        setNodes(prev => prev.map(n => selectedIds.includes(n.id) ? { ...n, files: [...(n.files || []), newFile] } : n));
      } else if (activeType === 'edge') {
        setEdges(prev => prev.map(e => selectedIds.includes(e.id) ? { ...e, files: [...(e.files || []), newFile] } : e));
      }
    };
    reader.readAsDataURL(file);
  }, [appState, saveHistory]);

  const handleDeleteFile = useCallback((fileId: string) => {
    saveHistory();
    const { selectedIds, activeType } = appState;
    if (activeType === 'node') {
      setNodes(prev => prev.map(n => selectedIds.includes(n.id) ? { ...n, files: n.files?.filter(f => f.id !== fileId) || [] } : n));
    } else if (activeType === 'edge') {
      setEdges(prev => prev.map(e => selectedIds.includes(e.id) ? { ...e, files: e.files?.filter(f => f.id !== fileId) || [] } : e));
    }
  }, [appState, saveHistory]);

  const handleDeleteItem = useCallback(() => {
    saveHistory();
    const { selectedIds, activeType } = appState;
    if (selectedIds.length === 0) return;
    if (activeType === 'node') {
      setNodes(prev => prev.filter(n => !selectedIds.includes(n.id)));
      setEdges(prev => prev.filter(e => !selectedIds.includes(e.fromId) && !selectedIds.includes(e.toId)));
    } else {
      setEdges(prev => prev.filter(e => !selectedIds.includes(e.id)));
    }
    setAppState(prev => ({ ...prev, selectedIds: [], activeType: null }));
  }, [appState, saveHistory]);

  const handleSelectSameColor = useCallback(() => {
    const { selectedIds, activeType } = appState;
    if (selectedIds.length === 0 || !activeType) return;
    let refColor = activeType === 'node' ? nodes.find(n => n.id === selectedIds[0])?.color : edges.find(e => e.id === selectedIds[0])?.color;
    if (!refColor) return;
    let newSelection = activeType === 'node' ? nodes.filter(n => n.color === refColor).map(n => n.id) : edges.filter(e => e.color === refColor).map(e => e.id);
    setAppState(prev => ({ ...prev, selectedIds: newSelection }));
  }, [appState, nodes, edges]);

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ nodes, edges }, null, 2)], { type: "application/json" });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `graph-project-${new Date().toISOString().slice(0,10)}.json`;
    a.click();
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        saveHistory();
        const result = JSON.parse(e.target?.result as string);
        if (result.nodes) setNodes(result.nodes);
        if (result.edges) setEdges(result.edges);
      } catch (err) { alert("Invalid JSON"); }
    };
    reader.readAsText(file);
  };

  // AI Architect: Apply Graph Structure from Files
  const handleApplyGraphFromAI = useCallback((newNodesRaw: any[], newEdgesRaw: any[]) => {
    saveHistory();

    // Map raw AI JSON to GraphNodeData
    const mappedNodes: GraphNodeData[] = newNodesRaw.map((n, idx) => ({
       id: crypto.randomUUID(),
       label: n.label,
       summary: n.summary || "",
       fullContent: n.fullContent || "",
       color: n.color || `hsl(${Math.random() * 360}, 70%, 50%)`,
       size: n.size || 1,
       position: [(Math.random() * 20) - 10, (Math.random() * 10) - 5, (Math.random() * 20) - 10], // Random pos for now
       files: []
    }));

    // Map raw AI JSON to GraphEdgeData
    const mappedEdges: GraphEdgeData[] = newEdgesRaw.map(e => {
       const fromNode = mappedNodes.find(n => n.label === e.fromLabel);
       const toNode = mappedNodes.find(n => n.label === e.toLabel);
       if (fromNode && toNode) {
         return {
           id: crypto.randomUUID(),
           fromId: fromNode.id,
           toId: toNode.id,
           label: e.label,
           color: '#888',
           size: 0.2,
           summary: e.summary || "",
           fullContent: "",
           files: [],
           direction: 'bidirectional'
         };
       }
       return null;
    }).filter(e => e !== null) as GraphEdgeData[];

    setNodes(mappedNodes);
    setEdges(mappedEdges);
  }, [saveHistory]);

  // AI Architect: Apply Changes (Shadow Copy logic)
  const handleApplyChangesFromAI = useCallback((changes: { modifiedNodes: {id: string, content: string}[], newNodes: any[], newEdges: any[] }) => {
     saveHistory();

     // 1. Handle Content Updates as Shadow Files
     if (changes.modifiedNodes && changes.modifiedNodes.length > 0) {
        setNodes(prev => prev.map(node => {
           const mod = changes.modifiedNodes.find(m => m.id === node.id);
           if (mod) {
             // Create a Shadow File instead of overwriting content directly
             const shadowFile: AttachedFile = {
               id: crypto.randomUUID(),
               name: `AI_Generated_Content_${Date.now()}.txt`,
               type: 'text/plain',
               content: `data:text/plain;base64,${btoa(unescape(encodeURIComponent(mod.content)))}`,
               isAiGenerated: true
             };
             return { ...node, files: [...node.files, shadowFile] };
           }
           return node;
        }));
     }

     // 2. Handle New Nodes
     if (changes.newNodes && changes.newNodes.length > 0) {
        const addedNodes: GraphNodeData[] = changes.newNodes.map(n => ({
          id: crypto.randomUUID(),
          label: n.label,
          summary: n.summary || "AI Generated",
          fullContent: n.fullContent || "",
          color: '#A020F0', // Purple for AI nodes
          size: 1,
          position: [(Math.random() * 20) - 10, 0, (Math.random() * 20) - 10],
          files: []
        }));
        setNodes(prev => [...prev, ...addedNodes]);
     }

     // 3. Handle New Edges (Note: this is complex as it needs to link to potentially new nodes)
     // For this prototype, we'll skip complex edge linking for auto-pilot to avoid ID mismatch errors,
     // or only link if nodes exist.
  }, [saveHistory]);

  const handlePointerOver = useCallback((e: any, data: GraphNodeData | GraphEdgeData) => {
    e.stopPropagation();
    if ('summary' in data) {
      setHoverData({ label: data.label, summary: data.summary || "", full: data.fullContent || "" });
    }
  }, []);

  const handlePointerOut = useCallback(() => { setHoverData(null); }, []);

  return (
    <div className={`w-full h-screen relative bg-gray-50 flex flex-col font-sans`}>
      <UIOverlay 
        appState={appState}
        nodes={nodes}
        edges={edges}
        cameraPos={cameraPosDisplay}
        uiPanels={uiPanels}
        setUiPanels={setUiPanels}
        setAppState={setAppState}
        onAddNode={handleAddNode}
        onToggleEdgeMode={() => setAppState(prev => ({ ...prev, mode: prev.mode === 'select' ? 'edge-start' : 'select', edgeStartNodeId: null }))}
        onUpdateItem={handleUpdateItem}
        onDeleteItem={handleDeleteItem}
        onExport={handleExport}
        onImport={handleImport}
        onCameraTeleport={(x, y, z) => setTargetCameraPos({ x, y, z })}
        hoverInfo={hoverData}
        onSelectSameColor={handleSelectSameColor}
        onFileUpload={handleFileUpload}
        onDeleteFile={handleDeleteFile}
        presentationMode={presentationMode}
        setPresentationMode={setPresentationMode}
        onRegeneratePresentation={regeneratePresentation}
        onCakePresentation={handleCakePresentation}
        onSmartGuide={handleSmartGuide}
        onAddFile={handleAddFile} 
        onRemoveFile={handleRemoveFile}
        onUndo={undo}
        onRedo={redo}
        canUndo={history.length > 0}
        canRedo={future.length > 0}
        onPushHistory={saveHistory}
        onApplyGraphFromAI={handleApplyGraphFromAI}
        onApplyChangesFromAI={handleApplyChangesFromAI}
      />

      <div className="flex-1 relative mt-12"> 
        <Canvas shadows={{ type: THREE.PCFShadowMap }} camera={{ position: [0, 10, 20], fov: 60 }} onPointerMissed={handleBackgroundClick}>
          <color attach="background" args={['#f0f2f5']} />
          <Suspense fallback={null}>
            <ambientLight intensity={0.6} />
            <pointLight position={[10, 20, 10]} intensity={0.8} castShadow />
            <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" />
            <CameraController targetPos={targetCameraPos} />
            <CameraReporter onUpdate={(pos) => setCameraPosDisplay({ x: pos.x, y: pos.y, z: pos.z })} />
            <KeyboardControls />
            <OrbitControls makeDefault enableDamping dampingFactor={0.1} mouseButtons={{ LEFT: undefined, MIDDLE: THREE.MOUSE.PAN, RIGHT: THREE.MOUSE.ROTATE }} />
            {nodes.map(node => (
              <GraphNode 
                key={node.id} 
                data={node} 
                isSelected={appState.selectedIds.includes(node.id)}
                isEdgeStart={appState.mode === 'edge-finish' && appState.edgeStartNodeId === node.id}
                onClick={handleNodeClick}
                onDoubleClick={handleDoubleClick}
                onPointerOver={handlePointerOver}
                onPointerOut={handlePointerOut}
                onDrag={handleDragNode}
                onDragStart={saveHistory} // Trigger save on drag start
                isDraggingEnabled={appState.mode === 'select'}
              />
            ))}
            {edges.map(edge => (
              <GraphEdge 
                key={edge.id}
                data={edge}
                fromNode={nodes.find(n => n.id === edge.fromId)}
                toNode={nodes.find(n => n.id === edge.toId)}
                isSelected={appState.selectedIds.includes(edge.id)}
                onClick={handleEdgeClick}
                onDoubleClick={handleDoubleClick}
                onPointerOver={handlePointerOver}
                onPointerOut={handlePointerOut}
              />
            ))}
          </Suspense>
        </Canvas>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, Suspense, useRef } from 'react';
import { Canvas, useThree, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid } from '@react-three/drei';
import * as THREE from 'three';
import { GraphNode } from './components/GraphNode';
import { GraphEdge } from './components/GraphEdge';
import { UIOverlay } from './components/UIOverlay';
import { GraphNodeData, GraphEdgeData, AppState, CameraState, UIPanelsState, AttachedFile, Language } from './types';
import { generatePresentation, generateCakePresentation, generateSmartGuide, generateModeContent } from './services/ai';
import { getDir, translations } from './utils/translations';

// Keyboard Control Component for Arrow navigation ONLY
const KeyboardControls = () => {
  const { camera, controls } = useThree();
  const [keys, setKeys] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => setKeys((k) => ({ ...k, [e.code]: true }));
    const handleKeyUp = (e: KeyboardEvent) => setKeys((k) => ({ ...k, [e.code]: false }));

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  useFrame((state, delta) => {
    // @ts-ignore
    if (!controls || !controls.enabled) return;

    const speed = 20 * delta; 
    const moveVector = new THREE.Vector3();

    const forward = new THREE.Vector3();
    camera.getWorldDirection(forward);
    forward.y = 0;
    forward.normalize();

    const right = new THREE.Vector3();
    right.crossVectors(forward, new THREE.Vector3(0, 1, 0));
    right.normalize();

    // Removed WASD to prevent typing conflict
    if (keys['ArrowUp']) moveVector.add(forward.multiplyScalar(speed));
    if (keys['ArrowDown']) moveVector.add(forward.multiplyScalar(-speed));
    if (keys['ArrowRight']) moveVector.add(right.multiplyScalar(-speed));
    if (keys['ArrowLeft']) moveVector.add(right.multiplyScalar(speed));

    if (moveVector.lengthSq() > 0) {
      camera.position.add(moveVector);
      // @ts-ignore
      if (controls.target) {
         // @ts-ignore
         controls.target.add(moveVector);
      }
    }
  });

  return null;
};

const CameraReporter: React.FC<{ onUpdate: (pos: THREE.Vector3) => void }> = ({ onUpdate }) => {
  const { camera } = useThree();
  useThree(({ camera }) => {
    onUpdate(camera.position);
  });
  return null;
};

const CameraController: React.FC<{ targetPos: CameraState | null }> = ({ targetPos }) => {
  const { camera, controls } = useThree();
  useEffect(() => {
    if (targetPos) {
      camera.position.set(targetPos.x, targetPos.y, targetPos.z);
      // @ts-ignore
      controls?.target?.set(targetPos.x, 0, targetPos.z - 10);
      // @ts-ignore
      controls?.update();
    }
  }, [targetPos, camera, controls]);
  return null;
};

const App: React.FC = () => {
  const [nodes, setNodes] = useState<GraphNodeData[]>([]);
  const [edges, setEdges] = useState<GraphEdgeData[]>([]);
  const [appState, setAppState] = useState<AppState>({
    nodes: [],
    edges: [],
    selectedIds: [],
    activeType: null,
    mode: 'select',
    edgeStartNodeId: null,
    appLanguage: 'fa',
    aiMode: 'presentation'
  });

  // History Stacks for Undo/Redo
  const [history, setHistory] = useState<{nodes: GraphNodeData[], edges: GraphEdgeData[]}[]>([]);
  const [future, setFuture] = useState<{nodes: GraphNodeData[], edges: GraphEdgeData[]}[]>([]);

  const [cameraPosDisplay, setCameraPosDisplay] = useState({ x: 0, y: 10, z: 20 });
  const [targetCameraPos, setTargetCameraPos] = useState<CameraState | null>(null);
  const [hoverData, setHoverData] = useState<{ label: string; summary: string; full: string } | null>(null);

  const [uiPanels, setUiPanels] = useState<UIPanelsState>({
    tools: true,
    properties: true,
    camera: true,
    hints: true,
    filePanel: false 
  });

  const [presentationMode, setPresentationMode] = useState<{ 
    isOpen: boolean; 
    content: string; 
    isLoading: boolean;
    activeFiles: AttachedFile[]; 
    targetLanguage: Language;
    activeItemId: string | null;
    modeTitle?: string;
  }>({
    isOpen: false,
    content: '',
    isLoading: false,
    activeFiles: [],
    targetLanguage: 'fa',
    activeItemId: null
  });

  // --- History Management ---
  const saveHistory = useCallback(() => {
    setHistory(prev => {
      // Optimization: Optionally check if the new state is identical to the last to avoid dups
      // But for simplicity and correctness with "pre-action" saving, we just push.
      return [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }];
    });
    setFuture([]); // Clear redo stack on new action
  }, [nodes, edges]);

  const undo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    const newHistory = history.slice(0, -1);

    setFuture(prev => [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }]);
    setNodes(previous.nodes);
    setEdges(previous.edges);
    setHistory(newHistory);
  }, [history, nodes, edges]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[future.length - 1];
    const newFuture = future.slice(0, -1);

    setHistory(prev => [...prev, { nodes: JSON.parse(JSON.stringify(nodes)), edges: JSON.parse(JSON.stringify(edges)) }]);
    setNodes(next.nodes);
    setEdges(next.edges);
    setFuture(newFuture);
  }, [future, nodes, edges]);

  // Keyboard Shortcuts for Undo/Redo
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
        if (e.shiftKey) {
          redo();
        } else {
          undo();
        }
      } else if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  useEffect(() => {
    const saved = localStorage.getItem('graph_pro_data');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setNodes(parsed.nodes || []);
        setEdges(parsed.edges || []);
      } catch (e) {
        console.error("Failed to load save data", e);
      }
    } else {
      handleAddNode();
    }
  }, []);

  useEffect(() => {
    const data = { nodes, edges };
    localStorage.setItem('graph_pro_data', JSON.stringify(data));
  }, [nodes, edges]);

  useEffect(() => {
    document.documentElement.dir = getDir(appState.appLanguage);
    document.documentElement.lang = appState.appLanguage;
  }, [appState.appLanguage]);

  const handleAddNode = useCallback(() => {
    saveHistory(); // Snapshot
    const newNode: GraphNodeData = {
      id: crypto.randomUUID(),
      label: `Node ${nodes.length + 1}`,
      summary: "Short summary...",
      fullContent: "", // Initialize empty as per requirement
      color: "#2196F3",
      size: 1,
      position: [(Math.random() * 10) - 5, 0, (Math.random() * 10) - 5],
      files: []
    };
    setNodes(prev => [...prev, newNode]);
    setAppState(prev => ({ ...prev, selectedIds: [newNode.id], activeType: 'node', mode: 'select' }));
  }, [nodes, saveHistory]);

  const handleNodeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();
    setAppState(prev => {
      if (prev.mode === 'select') {
        return { ...prev, selectedIds: [id], activeType: 'node' };
      } 
      else if (prev.mode === 'edge-start') {
        return { ...prev, edgeStartNodeId: id, mode: 'edge-finish' };
      } 
      else if (prev.mode === 'edge-finish') {
        if (prev.edgeStartNodeId && prev.edgeStartNodeId !== id) {
           saveHistory(); // Snapshot before creating edge
           const newEdge: GraphEdgeData = {
             id: crypto.randomUUID(),
             fromId: prev.edgeStartNodeId,
             toId: id,
             label: 'Connection',
             color: '#666666',
             size: 0.1,
             summary: "Connection...",
             fullContent: "",
             files: [],
             direction: 'bidirectional'
           };
           setEdges(current => [...current, newEdge]);
           return { ...prev, mode: 'select', selectedIds: [], activeType: null, edgeStartNodeId: null };
        }
        return { ...prev, mode: 'select' };
      }
      return prev;
    });
  }, [saveHistory]);

  const handleEdgeClick = useCallback((e: any, id: string) => {
    e.stopPropagation();
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, selectedIds: [id], activeType: 'edge' }));
    }
  }, [appState.mode]);

  const handleBackgroundClick = useCallback(() => {
    if (appState.mode === 'select') {
      setAppState(prev => ({ ...prev, selectedIds: [], activeType: null }));
    }
  }, [appState.mode]);

  // --- Image Save Handler (for Generated Images) ---
  const handleAddFile = useCallback((file: AttachedFile, itemId: string) => {
    saveHistory();
    // Save generated image to node/edge state
    const targetNode = nodes.find(n => n.id === itemId);
    if (targetNode) {
        setNodes(prev => prev.map(n => n.id === itemId ? { ...n, files: [...n.files, file] } : n));
        return;
    }
    const targetEdge = edges.find(e => e.id === itemId);
    if (targetEdge) {
        setEdges(prev => prev.map(e => e.id === itemId ? { ...e, files: [...e.files, file] } : e));
    }
  }, [nodes, edges, saveHistory]);

  const handleRemoveFile = useCallback((fileId: string, itemId: string) => {
    saveHistory();
    const targetNode = nodes.find(n => n.id === itemId);
    if (targetNode) {
        setNodes(prev => prev.map(n => n.id === itemId ? { ...n, files: n.files.filter(f => f.id !== fileId) } : n));
        return;
    }
    const targetEdge = edges.find(e => e.id === itemId);
    if (targetEdge) {
        setEdges(prev => prev.map(e => e.id === itemId ? { ...e, files: e.files.filter(f => f.id !== fileId) } : e));
    }
  }, [nodes, edges, saveHistory]);

  // --- AI Presentation Handlers ---
  const openPresentation = (content: string, item: GraphNodeData | GraphEdgeData, title: string, isLoading = false) => {
     setPresentationMode({
        isOpen: true,
        content: content,
        isLoading: isLoading,
        activeFiles: item.files || [],
        targetLanguage: appState.appLanguage,
        activeItemId: item.id,
        modeTitle: title
      });
  };

  const handleDoubleClick = useCallback(async (e: any, id: string) => {
    e.stopPropagation();
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      // Determine title based on current mode
      const t = translations[appState.appLanguage];
      let modeTitle = t.presentationTitle;
      if (appState.aiMode !== 'presentation') {
        modeTitle = t.modes[appState.aiMode];
      }

      // NO AUTOMATIC GENERATION here. Just open with existing content.
      openPresentation(target.fullContent || "", target, modeTitle, false);
    }
  }, [nodes, edges, appState.appLanguage, appState.aiMode]);

  const handleCakePresentation = useCallback(async () => {
    const id = appState.selectedIds[0];
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      const t = translations[appState.appLanguage];
      openPresentation(target.fullContent || "", target, t.cakePres, true);
      const htmlContent = await generateCakePresentation(target, appState.appLanguage);
      handleSaveModalContent(htmlContent); // Save result
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  }, [nodes, edges, appState.selectedIds, appState.appLanguage]);

  const handleSmartGuide = useCallback(async () => {
    const id = appState.selectedIds[0];
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      const t = translations[appState.appLanguage];
      openPresentation(target.fullContent || "", target, t.smartGuide, true);
      const htmlContent = await generateSmartGuide(target, nodes, edges, appState.appLanguage);
      handleSaveModalContent(htmlContent); // Save result
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  }, [nodes, edges, appState.selectedIds, appState.appLanguage]);

  const handleSaveModalContent = useCallback((newContent: string) => {
     saveHistory();
     const id = presentationMode.activeItemId;
     if (!id) return;

     // Update Node/Edge State
     const targetNode = nodes.find(n => n.id === id);
     if (targetNode) {
        setNodes(prev => prev.map(n => n.id === id ? { ...n, fullContent: newContent } : n));
     } else {
        const targetEdge = edges.find(e => e.id === id);
        if (targetEdge) {
            setEdges(prev => prev.map(e => e.id === id ? { ...e, fullContent: newContent } : e));
        }
     }
  }, [nodes, edges, presentationMode.activeItemId, saveHistory]);

  const regeneratePresentation = async (lang: Language) => {
    const id = presentationMode.activeItemId;
    if (!id) return;
    const target = nodes.find(n => n.id === id) || edges.find(e => e.id === id);
    if (target) {
      setPresentationMode(prev => ({ ...prev, isLoading: true, targetLanguage: lang }));
      const htmlContent = await generateModeContent(target, appState.aiMode, lang);
      handleSaveModalContent(htmlContent); // Save result
      setPresentationMode(prev => ({ ...prev, content: htmlContent, isLoading: false }));
    }
  };

  const handleDragNode = useCallback((id: string, newPos: [number, number, number]) => {
    // Note: saveHistory is triggered by onDragStart in GraphNode component
    setNodes(prev => {
      const draggedNode = prev.find(n => n.id === id);
      if (!draggedNode) return prev;
      const dx = newPos[0] - draggedNode.position[0];
      const dy = newPos[1] - draggedNode.position[1];
      const dz = newPos[2] - draggedNode.position[2];

      if (appState.selectedIds.includes(id)) {
        return prev.map(n => {
          if (appState.selectedIds.includes(n.id)) {
             return { ...n, position: [n.position[0] + dx, n.position[1] + dy, n.position[2] + dz] };
          }
          return n;
        });
      }
      return prev.map(n => n.id === id ? { ...n, position: newPos } : n);
    });
  }, [appState.selectedIds]);

  const handleUpdateItem = useCallback((id: string, type: 'node' | 'edge', data: any) => {
    // Note: saveHistory is triggered by onPushHistory (onFocus/onClick) in UIOverlay
    const targetIds = appState.selectedIds.includes(id) ? appState.selectedIds : [id];
    if (type === 'node') {
      setNodes(prev => prev.map(n => targetIds.includes(n.id) ? { ...n, ...data } : n));
    } else {
      setEdges(prev => prev.map(e => targetIds.includes(e.id) ? { ...e, ...data } : e));
    }
  }, [appState.selectedIds]);

  const handleFileUpload = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      saveHistory();
      const result = e.target?.result as string; 
      const newFile: AttachedFile = {
        id: crypto.randomUUID(),
        name: file.name,
        type: file.type,
        content: result
      };
      const { selectedIds, activeType } = appState;
      if (activeType === 'node') {
        setNodes(prev => prev.map(n => selectedIds.includes(n.id) ? { ...n, files: [...(n.files || []), newFile] } : n));
      } else if (activeType === 'edge') {
        setEdges(prev => prev.map(e => selectedIds.includes(e.id) ? { ...e, files: [...(e.files || []), newFile] } : e));
      }
    };
    reader.readAsDataURL(file);
  }, [appState, saveHistory]);

  const handleDeleteFile = useCallback((fileId: string) => {
    saveHistory();
    const { selectedIds, activeType } = appState;
    if (activeType === 'node') {
      setNodes(prev => prev.map(n => selectedIds.includes(n.id) ? { ...n, files: n.files?.filter(f => f.id !== fileId) || [] } : n));
    } else if (activeType === 'edge') {
      setEdges(prev => prev.map(e => selectedIds.includes(e.id) ? { ...e, files: e.files?.filter(f => f.id !== fileId) || [] } : e));
    }
  }, [appState, saveHistory]);

  const handleDeleteItem = useCallback(() => {
    saveHistory();
    const { selectedIds, activeType } = appState;
    if (selectedIds.length === 0) return;
    if (activeType === 'node') {
      setNodes(prev => prev.filter(n => !selectedIds.includes(n.id)));
      setEdges(prev => prev.filter(e => !selectedIds.includes(e.fromId) && !selectedIds.includes(e.toId)));
    } else {
      setEdges(prev => prev.filter(e => !selectedIds.includes(e.id)));
    }
    setAppState(prev => ({ ...prev, selectedIds: [], activeType: null }));
  }, [appState, saveHistory]);

  const handleSelectSameColor = useCallback(() => {
    const { selectedIds, activeType } = appState;
    if (selectedIds.length === 0 || !activeType) return;
    let refColor = activeType === 'node' ? nodes.find(n => n.id === selectedIds[0])?.color : edges.find(e => e.id === selectedIds[0])?.color;
    if (!refColor) return;
    let newSelection = activeType === 'node' ? nodes.filter(n => n.color === refColor).map(n => n.id) : edges.filter(e => e.color === refColor).map(e => e.id);
    setAppState(prev => ({ ...prev, selectedIds: newSelection }));
  }, [appState, nodes, edges]);

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ nodes, edges }, null, 2)], { type: "application/json" });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `graph-project-${new Date().toISOString().slice(0,10)}.json`;
    a.click();
  };

  const handleImport = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        saveHistory();
        const result = JSON.parse(e.target?.result as string);
        if (result.nodes) setNodes(result.nodes);
        if (result.edges) setEdges(result.edges);
      } catch (err) { alert("Invalid JSON"); }
    };
    reader.readAsText(file);
  };

  // AI Architect: Apply Graph Structure from Files
  const handleApplyGraphFromAI = useCallback((newNodesRaw: any[], newEdgesRaw: any[]) => {
    saveHistory();

    // Map raw AI JSON to GraphNodeData
    const mappedNodes: GraphNodeData[] = newNodesRaw.map((n, idx) => ({
       id: crypto.randomUUID(),
       label: n.label,
       summary: n.summary || "",
       fullContent: n.fullContent || "",
       color: n.color || `hsl(${Math.random() * 360}, 70%, 50%)`,
       size: n.size || 1,
       position: [(Math.random() * 20) - 10, (Math.random() * 10) - 5, (Math.random() * 20) - 10], // Random pos for now
       files: []
    }));

    // Map raw AI JSON to GraphEdgeData
    const mappedEdges: GraphEdgeData[] = newEdgesRaw.map(e => {
       const fromNode = mappedNodes.find(n => n.label === e.fromLabel);
       const toNode = mappedNodes.find(n => n.label === e.toLabel);
       if (fromNode && toNode) {
         return {
           id: crypto.randomUUID(),
           fromId: fromNode.id,
           toId: toNode.id,
           label: e.label,
           color: '#888',
           size: 0.2,
           summary: e.summary || "",
           fullContent: "",
           files: [],
           direction: 'bidirectional'
         };
       }
       return null;
    }).filter(e => e !== null) as GraphEdgeData[];

    setNodes(mappedNodes);
    setEdges(mappedEdges);
  }, [saveHistory]);

  // AI Architect: Apply Changes (Shadow Copy logic)
  const handleApplyChangesFromAI = useCallback((changes: { modifiedNodes: {id: string, content: string}[], newNodes: any[], newEdges: any[] }) => {
     saveHistory();

     // 1. Handle Content Updates as Shadow Files
     if (changes.modifiedNodes && changes.modifiedNodes.length > 0) {
        setNodes(prev => prev.map(node => {
           const mod = changes.modifiedNodes.find(m => m.id === node.id);
           if (mod) {
             // Create a Shadow File instead of overwriting content directly
             const shadowFile: AttachedFile = {
               id: crypto.randomUUID(),
               name: `AI_Generated_Content_${Date.now()}.txt`,
               type: 'text/plain',
               content: `data:text/plain;base64,${btoa(unescape(encodeURIComponent(mod.content)))}`,
               isAiGenerated: true
             };
             return { ...node, files: [...node.files, shadowFile] };
           }
           return node;
        }));
     }

     // 2. Handle New Nodes
     if (changes.newNodes && changes.newNodes.length > 0) {
        const addedNodes: GraphNodeData[] = changes.newNodes.map(n => ({
          id: crypto.randomUUID(),
          label: n.label,
          summary: n.summary || "AI Generated",
          fullContent: n.fullContent || "",
          color: '#A020F0', // Purple for AI nodes
          size: 1,
          position: [(Math.random() * 20) - 10, 0, (Math.random() * 20) - 10],
          files: []
        }));
        setNodes(prev => [...prev, ...addedNodes]);
     }

     // 3. Handle New Edges (Note: this is complex as it needs to link to potentially new nodes)
     // For this prototype, we'll skip complex edge linking for auto-pilot to avoid ID mismatch errors,
     // or only link if nodes exist.
  }, [saveHistory]);

  const handlePointerOver = useCallback((e: any, data: GraphNodeData | GraphEdgeData) => {
    e.stopPropagation();
    if ('summary' in data) {
      setHoverData({ label: data.label, summary: data.summary || "", full: data.fullContent || "" });
    }
  }, []);

  const handlePointerOut = useCallback(() => { setHoverData(null); }, []);

  return (
    <div className={`w-full h-screen relative bg-gray-50 flex flex-col font-sans`}>
      <UIOverlay 
        appState={appState}
        nodes={nodes}
        edges={edges}
        cameraPos={cameraPosDisplay}
        uiPanels={uiPanels}
        setUiPanels={setUiPanels}
        setAppState={setAppState}
        onAddNode={handleAddNode}
        onToggleEdgeMode={() => setAppState(prev => ({ ...prev, mode: prev.mode === 'select' ? 'edge-start' : 'select', edgeStartNodeId: null }))}
        onUpdateItem={handleUpdateItem}
        onDeleteItem={handleDeleteItem}
        onExport={handleExport}
        onImport={handleImport}
        onCameraTeleport={(x, y, z) => setTargetCameraPos({ x, y, z })}
        hoverInfo={hoverData}
        onSelectSameColor={handleSelectSameColor}
        onFileUpload={handleFileUpload}
        onDeleteFile={handleDeleteFile}
        presentationMode={presentationMode}
        setPresentationMode={setPresentationMode}
        onRegeneratePresentation={regeneratePresentation}
        onCakePresentation={handleCakePresentation}
        onSmartGuide={handleSmartGuide}
        onAddFile={handleAddFile} 
        onRemoveFile={handleRemoveFile}
        onUndo={undo}
        onRedo={redo}
        canUndo={history.length > 0}
        canRedo={future.length > 0}
        onPushHistory={saveHistory}
        onApplyGraphFromAI={handleApplyGraphFromAI}
        onApplyChangesFromAI={handleApplyChangesFromAI}
      />

      <div className="flex-1 relative mt-12"> 
        <Canvas camera={{ position: [0, 10, 20], fov: 60 }} onPointerMissed={handleBackgroundClick}>
          <color attach="background" args={['#f0f2f5']} />
          <Suspense fallback={null}>
            <ambientLight intensity={0.6} />
            <pointLight position={[10, 20, 10]} intensity={0.8} />
            <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" />
            <CameraController targetPos={targetCameraPos} />
            <CameraReporter onUpdate={(pos) => setCameraPosDisplay({ x: pos.x, y: pos.y, z: pos.z })} />
            <KeyboardControls />
            <OrbitControls makeDefault enableDamping dampingFactor={0.1} mouseButtons={{ LEFT: undefined, MIDDLE: THREE.MOUSE.PAN, RIGHT: THREE.MOUSE.ROTATE }} />
            {nodes.map(node => (
              <GraphNode 
                key={node.id} 
                data={node} 
                isSelected={appState.selectedIds.includes(node.id)}
                isEdgeStart={appState.mode === 'edge-finish' && appState.edgeStartNodeId === node.id}
                onClick={handleNodeClick}
                onDoubleClick={handleDoubleClick}
                onPointerOver={handlePointerOver}
                onPointerOut={handlePointerOut}
                onDrag={handleDragNode}
                onDragStart={saveHistory} // Trigger save on drag start
                isDraggingEnabled={appState.mode === 'select'}
              />
            ))}
            {edges.map(edge => (
              <GraphEdge 
                key={edge.id}
                data={edge}
                fromNode={nodes.find(n => n.id === edge.fromId)}
                toNode={nodes.find(n => n.id === edge.toId)}
                isSelected={appState.selectedIds.includes(edge.id)}
                onClick={handleEdgeClick}
                onDoubleClick={handleDoubleClick}
                onPointerOver={handlePointerOver}
                onPointerOut={handlePointerOut}
              />
            ))}
          </Suspense>
        </Canvas>
      </div>
    </div>
  );
};

export default App;

